import styles from './PlanningTasklistBlock.module.css'

export const planningTasklistBlockAttribute = 'data-planning-tasklist-block'

export interface PlanningTasklist {
  name: string
  tasks: PlanningTask[]
}

interface PlanningTaskBase {
  tag: string
  dependencyTags?: string[]
  title: string
  repository?: string
  description: string
}

interface PlanningTaskWithPullRequest extends PlanningTaskBase {
  pullRequest: number
  repository: string
}

interface PlanningTaskWithoutPullRequest extends PlanningTaskBase {
  pullRequest?: never
}

type PlanningTask = PlanningTaskWithPullRequest | PlanningTaskWithoutPullRequest

const isPlanningTask = (obj: unknown): obj is PlanningTask => {
  if (typeof obj !== 'object' || obj === null) return false

  // Check for required properties
  if (!('tag' in obj) || typeof obj.tag !== 'string') return false
  if (!('title' in obj) || typeof obj.title !== 'string') return false
  if (!('description' in obj) || typeof obj.description !== 'string') return false

  // Check optional properties are in the correct format
  if ('dependencyTags' in obj && !Array.isArray(obj.dependencyTags)) return false
  if ('repository' in obj && typeof obj.repository !== 'string') return false
  if ('pullRequest' in obj && typeof obj.pullRequest !== 'number') return false

  // Validate that if pullRequest is defined, repository must also be defined
  const hasPullRequest = 'pullRequest' in obj && obj.pullRequest != null
  const hasRepository = 'repository' in obj && obj.repository != null && obj.repository !== ''
  if (hasPullRequest && !hasRepository) {
    return false
  }

  return true
}

export const PlanningTasklist = {
  /** Being extremely defensive about the types here allows us to safely handle partial data and bad model results. */
  fromUnknown: (data: unknown): PlanningTasklist | null => {
    if (typeof data !== 'object' || data == null) return null

    const name = 'name' in data && typeof data.name === 'string' ? data.name : 'Tasklist'
    const item: PlanningTasklist = {name, tasks: []}

    if ('tasks' in data && Array.isArray(data.tasks)) {
      for (const taskData of data.tasks) {
        if (typeof taskData !== 'object' || taskData == null) continue

        if (isPlanningTask(taskData)) {
          item.tasks.push(taskData)
        }
      }
    }

    return item
  },
}

const parseTasklistData = (yaml: string) => {
  try {
    const result = load(yaml)
    return PlanningTasklist.fromUnknown(result)
  } catch {
    sendEvent('copilot.planning_tasklist', {type: 'MALFORMED_YAML', mode: 'immersive'})
    return null
  }
}

interface TasklistItemProps {
  task: VersionedPlanningTask
  isStreaming: boolean
  onClick: () => void
}

function TasklistItem({task, isStreaming, onClick}: TasklistItemProps) {
  return (
    // Used by `useCAPIQuery` within `usePlanningTaskPullRequest` for tracking authentication failures in CAPI requests.
    <ConsecutiveCAPI401sProvider>
      <TasklistItemImpl task={task} isStreaming={isStreaming} onClick={onClick} />
    </ConsecutiveCAPI401sProvider>
  )
}

function TasklistItemImpl({task, isStreaming, onClick}: TasklistItemProps) {
  const {pullRequest, isLoading: isPullRequestDataLoading} = usePlanningTaskPullRequest(task)
  const {versionedItems} = useContentPreview()
  const version = getRevisionNumber(task.id, versionedItems)

  const getIcon = () => {
    if (isStreaming || isPullRequestDataLoading) {
      return <Spinner size="small" className={disableStreamingFadeIn} />
    }

    if (pullRequest != null) {
      return <GitPullRequestIcon />
    }

    return <TasklistIcon />
  }

  return (
    <ActionList.Item key={task.id} onSelect={onClick} className="py-2">
      <ActionList.LeadingVisual>{getIcon()}</ActionList.LeadingVisual>
      {task.name}
      <ActionList.TrailingVisual>{version != null && <VersionName version={version} />}</ActionList.TrailingVisual>
    </ActionList.Item>
  )
}

export interface PlanningTasklistBlockProps {
  yaml: string
  isStreaming?: boolean
}

export function PlanningTasklistBlock({yaml, isStreaming}: PlanningTasklistBlockProps) {
  const [fromStreaming, setFromStreaming] = useState(isStreaming)
  const openedTasksRef = useRef<Set<string>>(new Set())

  useEffect(() => {
    if (isStreaming) {
      setFromStreaming(true)
    }
  }, [isStreaming])

  const {updateItem, openItem, openPreviewPane} = useContentPreview()
  const {messageId, messageIndex, setHasAutoOpenedPreviewPane} = useContentPreviewBlockContext()

  // Employ `useMemo + useRef` instead of `useState` to avoid asynchronous state updates
  // Since the order of versionedItems matters, we need to ensure that we call `updateItem` with the latest data
  // immediately after the YAML is changed.
  const tasklistRef = useRef<PlanningTasklist>({name: 'Tasklist', tasks: []})
  const tasklist = useMemo(() => {
    const parsedTaskData = parseTasklistData(yaml)
    if (parsedTaskData != null) {
      tasklistRef.current = parsedTaskData
      return parsedTaskData
    } else {
      // Ignore bad data due to partially streamed YAML
      return tasklistRef.current
    }
  }, [yaml])

  // Generate IDs for all tasks and update items for each one
  const taskItems: VersionedPlanningTask[] = useMemo(() => {
    return tasklist.tasks.map(taskItem => {
      const id = `planning-task:${taskItem.tag}#${messageIndex}` as const

      const {title, ...restOfTaskItem} = taskItem

      return {
        ...restOfTaskItem,
        name: title,
        messageId,
        id,
        type: 'planning-task',
        isUserEdited: false,
        isStreaming,
      }
    })
  }, [tasklist, messageIndex, messageId, isStreaming])

  const {convertAllToDraftIssues} = useConvertAllToDraftIssues(taskItems)

  const openTask = useCallback(
    (task: VersionedPlanningTask, options: {selectItem?: boolean} = {}) => {
      const {selectItem} = options

      openItem(task.id, selectItem)
      openPreviewPane()
      setHasAutoOpenedPreviewPane(true)

      sendEvent('copilot.planning_tasklist', {type: 'TASK_OPENED', mode: 'immersive'})
    },
    [openItem, openPreviewPane, setHasAutoOpenedPreviewPane],
  )

  useEffect(() => {
    // Open task previews
    for (let i = 0; i < taskItems.length; i++) {
      const task = taskItems[i]
      updateItem(task!)

      // Only open once
      if (fromStreaming && !openedTasksRef.current.has(task!.id)) {
        openedTasksRef.current.add(task!.id)
        openTask(task!, {selectItem: i === 0})
      }
    }
  }, [taskItems, updateItem, openTask, fromStreaming])

  const onClick = useCallback((task: VersionedPlanningTask) => openTask(task), [openTask])

  useEffect(() => sendEvent('copilot.planning_tasklist', {type: 'BLOCK_RENDERED', mode: 'immersive'}), [])

  useEffect(() => {
    if (!isStreaming && fromStreaming && taskItems.length === 0) {
      sendEvent('copilot.planning_tasklist', {type: 'NO_TASKS', mode: 'immersive'})
    }
  }, [fromStreaming, isStreaming, taskItems])

  const taskItemsMap = taskItems.map(task => (
    <TasklistItem key={task.id} task={task} isStreaming={!!isStreaming} onClick={() => onClick(task)} />
  ))

  const blankSlate = <span>No tasks were created, please retry.</span>

  return (
    <div className={styles.container}>
      <ActionList variant="full" showDividers>
        <ActionList.Heading as="h4" className="mx-3 mt-3 mb-1 d-flex flex-items-center">
          {tasklist?.name ?? 'Tasklist'}
          <CounterLabel className="ml-2 pb-1">{taskItems.length}</CounterLabel>
          {taskItems.length > 0 && (
            <div className="flex-justify-end d-flex flex-1">
              <ActionMenu>
                <ActionMenu.Anchor>
                  <IconButton
                    icon={KebabHorizontalIcon}
                    variant="invisible"
                    aria-label={`Tasklist '${tasklist?.name ?? ''}' options`}
                  />
                </ActionMenu.Anchor>

                <ActionMenuOverlay>
                  <ActionList>
                    <ActionList.Item onSelect={convertAllToDraftIssues}>Draft all as issues</ActionList.Item>
                  </ActionList>
                </ActionMenuOverlay>
              </ActionMenu>
            </div>
          )}
        </ActionList.Heading>
        {!isStreaming && taskItems.length === 0 ? blankSlate : taskItemsMap}
      </ActionList>
    </div>
  )
}

try{ TasklistItem.displayName ||= 'TasklistItem' } catch {}
try{ TasklistItemImpl.displayName ||= 'TasklistItemImpl' } catch {}
try{ PlanningTasklistBlock.displayName ||= 'PlanningTasklistBlock' } catch {}