export type Result<T> = SuccessResult<T> | ErrorResult

export function SuccessResult<T>(data: T): SuccessResult<T> {
  return {success: true, data}
}

interface SuccessResult<T> {
  success: true
  data: T
}

export function ErrorResult(err: unknown, res?: Response): ErrorResult {
  return {success: false, error: extractErrorMessage(err), httpStatus: res?.status}
}

interface ErrorResult {
  success: false
  error: string
  httpStatus?: number
}

const defaultMessage = 'Unknown error'

export function extractErrorMessage(err: unknown, overrideDefault?: string): string {
  if (!err) return overrideDefault ?? defaultMessage

  if (typeof err === 'string') return err

  if (typeof err !== 'object') return overrideDefault ?? defaultMessage

  if ('message' in err && typeof err.message === 'string') return err.message

  if ('error' in err && err.error === 'string') return err.error

  return overrideDefault ?? defaultMessage
}
