import type {CopilotSpaceBaseRole, CopilotSpaceVisibility} from '@github-ui/copilot-chat/utils/copilot-chat-types'

export function getVisibilityText(
  visibility: CopilotSpaceVisibility,
  baseRole: CopilotSpaceBaseRole,
  isShared: boolean = false,
): string {
  if (isShared) return 'Shared'

  switch (baseRole) {
    case 'custom_copilot_reader':
    case 'custom_copilot_writer':
    case 'custom_copilot_admin':
      return 'Shared'
  }

  switch (visibility) {
    case 'org_public':
      return 'Shared'
  }

  return 'Private'
}
