import {fetchMilestones} from '@github-ui/item-picker-milestone-relay'
import {useQuery} from '@github-ui/react-query'
import {useRelayEnvironment} from 'react-relay'

export function useMilestoneQuery({
  owner,
  repo,
  milestone,
}: {
  owner: string | undefined
  repo: string | undefined
  milestone: string | undefined
}) {
  const environment = useRelayEnvironment()

  return useQuery({
    queryKey: ['copilot-immersive-milestones', JSON.stringify(environment), owner, repo, milestone],
    queryFn: async () => {
      if (!owner || !repo || !milestone) return null

      const milestones = await fetchMilestones(environment, {
        owner,
        repo,
        query: milestone,
        count: 1,
      })

      return milestones[0] ?? null
    },
  })
}
