import {verifiedFetch} from '@github-ui/verified-fetch'
import type {Loop} from '../types/app'
import type {Execution, NodeExecution} from '../types/execution'
import {ErrorResult, SuccessResult, type Result} from './result'
import type {Version} from '../types/version'

interface ListLoopsOperation {
  operation: 'list-loops'
}

interface CreateLoopOperation {
  operation: 'create-loop'
  loop: Partial<Loop>
}

interface UpdateLoopOperation {
  operation: 'update-loop'
  loopID: string
  version: string
  loop: Loop
}

interface GetLoopOperation {
  operation: 'get-loop'
  loopID: string
  versionConstraint: string
}

interface DeleteLoopOperation {
  operation: 'delete-loop'
  loopID: string
}

interface ListLoopVersionsOperation {
  operation: 'list-loop-versions'
  loopID: string
}

interface CreateExecutionOperation {
  operation: 'create-execution'
  loopID: string
  version: string
  executionInit: {
    inputValues?: Record<string, string>
    nodes?: Record<string, NodeExecution>
  }
  shareID?: string
}

interface GetExecutionOperation {
  operation: 'get-execution'
  loopID: string
  version: string
  executionID: string
}

interface UpdateNodeExecutionOperation {
  operation: 'update-node-execution'
  loopID: string
  version: string
  executionID: string
  nodeID: string
  nodeExecution: NodeExecution
  shareID?: string
}

interface ShareLoopOperation {
  operation: 'share-loop'
  loopID: string
}

interface UnshareLoopOperation {
  operation: 'unshare-loop'
  loopID: string
}

type LoopClientOperation =
  | ListLoopsOperation
  | CreateLoopOperation
  | UpdateLoopOperation
  | GetLoopOperation
  | DeleteLoopOperation
  | ListLoopVersionsOperation
  | CreateExecutionOperation
  | GetExecutionOperation
  | UpdateNodeExecutionOperation
  | ShareLoopOperation
  | UnshareLoopOperation

export class LoopsClient {
  #clientURL: string

  constructor(clientURL: string) {
    this.#clientURL = clientURL
  }

  listLoops() {
    return this.#sendRequest<Loop[]>({operation: 'list-loops'})
  }

  listLoopVersions(loopID: string) {
    return this.#sendRequest<Version[]>({operation: 'list-loop-versions', loopID})
  }

  createLoop(loop: Partial<Loop>) {
    return this.#sendRequest<Loop>({operation: 'create-loop', loop})
  }

  updateLoop(loopID: string, version: string, loop: Loop) {
    return this.#sendRequest<Loop>({operation: 'update-loop', loopID, version, loop})
  }

  getLoop(loopID: string, versionConstraint: string) {
    return this.#sendRequest<Loop>({operation: 'get-loop', loopID, versionConstraint})
  }

  deleteLoop(loopID: string) {
    return this.#sendRequest<void>({operation: 'delete-loop', loopID})
  }

  createExecution(
    loopID: string,
    version: string,
    nodes?: Record<string, NodeExecution>,
    inputValues?: Record<string, string>,
    shareID?: string,
  ) {
    return this.#sendRequest<Execution>({
      operation: 'create-execution',
      loopID,
      version,
      executionInit: {
        inputValues,
        nodes,
      },
      shareID,
    })
  }

  getExecution(loopID: string, version: string, executionID: string) {
    return this.#sendRequest<Execution>({operation: 'get-execution', loopID, version, executionID})
  }

  updateNodeExecution(
    loopID: string,
    version: string,
    executionID: string,
    nodeID: string,
    nodeExecution: NodeExecution,
    shareID?: string,
  ) {
    return this.#sendRequest<NodeExecution>({
      operation: 'update-node-execution',
      loopID,
      version,
      executionID,
      nodeID,
      nodeExecution,
      shareID,
    })
  }

  shareLoop(loopID: string) {
    return this.#sendRequest<void>({operation: 'share-loop', loopID})
  }

  unshareLoop(loopID: string) {
    return this.#sendRequest<void>({operation: 'unshare-loop', loopID})
  }

  async #sendRequest<TRes>(operation: LoopClientOperation): Promise<Result<TRes>> {
    const res = await verifiedFetch(this.#clientURL, {
      method: 'POST',
      body: JSON.stringify(operation),
      headers: {'Content-Type': 'application/json'},
    })
    if (!res.ok) {
      const errResponseText = await res.text()
      try {
        return ErrorResult(JSON.parse(errResponseText), res)
      } catch (err: unknown) {
        return ErrorResult(err, res)
      }
    }

    // Some requests return no content - do not try to get json in this case
    const data = res.status === 204 ? undefined : await res.json()
    return SuccessResult(data)
  }
}
