import type {ProjectPickerProject} from '@github-ui/item-picker/ProjectPicker'
import {commitUpdateIssueProjectsMutation} from '@github-ui/item-picker/updateIssueProjectsMutation'
import {commitMutation, graphql} from 'react-relay'
import type {Environment, IEnvironment} from 'relay-runtime'

import type {UpdateIssueInput, updateIssueMutationMutation} from './__generated__/updateIssueMutationMutation.graphql'

export type UpdatedIssue = Exclude<
  Exclude<updateIssueMutationMutation['response']['updateIssue'], null | undefined>['issue'],
  null | undefined
>

export type OnUpdateProps = {
  issue: UpdatedIssue
}

export type ProjectUpdateError = {
  projectId: string
  projectTitle: string
  operation: 'add' | 'remove'
  error: string
}

export type UpdateIssueInputParams = {
  issueId: string
  clientMutationId: string
  title?: string
  assigneeIds?: string[]
  labelIds?: string[]
  milestoneId?: string | null
  issueTypeId?: string | null
  projects?: ProjectPickerProject[]
} & ({body?: never; bodyVersion?: never} | {body: string; bodyVersion: string})

export type CommitUpdateIssueMutationParams = {
  environment: IEnvironment
  input: UpdateIssueInputParams
  onError?: (error: Error | {type: string; projectErrors?: ProjectUpdateError[]}) => void
  onCompleted?: (response: OnUpdateProps) => void
}

export function commitUpdateIssueMutation({
  environment,
  input: {
    issueId,
    clientMutationId,
    title,
    body,
    bodyVersion,
    assigneeIds,
    labelIds,
    milestoneId,
    issueTypeId,
    projects,
  },
  onError,
  onCompleted,
}: CommitUpdateIssueMutationParams) {
  const inputHash: UpdateIssueInput = {
    id: issueId,
    clientMutationId,
  }

  if (title !== undefined) {
    inputHash.title = title
  }

  if (body !== undefined) {
    if (bodyVersion === '') {
      throw new Error('bodyVersion cannot be empty when body is provided')
    }
    inputHash.body = body
    // bodyVersion is required when body is provided due to type constraints
    inputHash.bodyVersion = bodyVersion
  }

  if (assigneeIds !== undefined) {
    inputHash.assigneeIds = assigneeIds
  }

  if (labelIds !== undefined) {
    inputHash.labelIds = labelIds
  }

  if (milestoneId !== undefined) {
    inputHash.milestoneId = milestoneId
  }

  if (issueTypeId !== undefined) {
    inputHash.issueTypeId = issueTypeId
  }

  // Check if only id is present in inputHash (no actual updates)
  if (Object.keys(inputHash).length === 2 && inputHash.id && inputHash.clientMutationId) {
    throw new Error('At least one field must be provided for update')
  }

  return commitMutation<updateIssueMutationMutation>(environment, {
    mutation: graphql`
      mutation updateIssueMutationMutation($input: UpdateIssueInput!) @raw_response_type {
        updateIssue(input: $input) {
          issue {
            id
            number
            url
            title
            body
            bodyVersion
            assignees(first: 10) {
              nodes {
                id
                login
                name
                avatarUrl
              }
            }
            labels(first: 20) {
              nodes {
                id
                name
                color
                description
              }
            }
            milestone {
              id
              title
              description
              state
            }
            issueType {
              id
              name
              color
              description
            }
            repository {
              databaseId
              id
              name
              owner {
                login
              }
            }
            projectItemsNext(first: 20) {
              edges {
                node {
                  id
                  project {
                    id
                    title
                    closed
                    number
                    url
                    viewerCanUpdate
                    hasReachedItemsLimit
                  }
                }
              }
            }
          }
          errors {
            message
          }
        }
      }
    `,
    variables: {
      input: inputHash,
    },
    onError: error => onError?.(error),
    onCompleted: response => {
      if (!response.updateIssue?.issue) {
        let errorMessage = 'Unable to update issue'

        const errors = response.updateIssue?.errors as Error[] | null | undefined
        if (errors && errors.length > 0) {
          for (const e of errors) {
            reportError(formatError(e.message))
          }
          errorMessage = formatFormErrorMessage(errors) ?? errorMessage
        }

        return onError?.(new Error(errorMessage))
      }

      const updatedIssue = response.updateIssue.issue

      // Handle project updates if projects are provided (including empty array to remove all)
      if (projects !== undefined) {
        // Extract current projects from the updated issue response
        const currentProjectItems =
          updatedIssue.projectItemsNext?.edges
            ?.filter((edge): edge is NonNullable<typeof edge> => edge != null)
            ?.map(edge => edge.node)
            ?.filter((node): node is NonNullable<typeof node> => node != null) ?? []

        const currentProjects: ProjectPickerProject[] = currentProjectItems.map(node => ({
          id: node.project.id,
          title: node.project.title,
          closed: node.project.closed,
          number: node.project.number,
          url: node.project.url,
          viewerCanUpdate: node.project.viewerCanUpdate,
          hasReachedItemsLimit: node.project.hasReachedItemsLimit,
          __typename: 'ProjectV2' as const,
        }))

        // Start project updates immediately (don't await)
        void (async () => {
          try {
            // TypeScript assertion: projects is guaranteed to be defined here (can be empty array)
            await updateIssueProjects(issueId, projects, currentProjects, currentProjectItems, environment)
          } catch (projectError: unknown) {
            // Project updates failed, but issue was updated successfully
            // Pass the project error information to the error handler
            if (projectError instanceof Error && 'projectErrors' in projectError) {
              const errorWithDetails = projectError as Error & {projectErrors: ProjectUpdateError[]}
              onError?.({type: 'PROJECT_UPDATE_FAILED', projectErrors: errorWithDetails.projectErrors})
            }
          }
        })()
      }

      // Call onCompleted immediately, don't wait for project updates
      onCompleted?.({issue: updatedIssue})
    },
  })
}

function formatError(message: string) {
  return new Error(`Issue update mutation failed with error: ${message}`)
}

function formatFormErrorMessage(errors: Error[]) {
  const errorMessages = errors
    .map(err => err?.message)
    .filter(Boolean)
    .join(', ')

  // Some gql errors start with lowercase letters, so normalizing it
  const cleanedErrorMessages = errorMessages
    ? errorMessages.charAt(0).toUpperCase() + errorMessages.slice(1)
    : undefined

  return cleanedErrorMessages
}

async function updateIssueProjects(
  issueId: string,
  desiredProjects: ProjectPickerProject[],
  currentProjects: ProjectPickerProject[],
  currentProjectItems: Array<{id: string; project: {id: string}}>,
  environment: IEnvironment,
) {
  const projectsToAdd = desiredProjects.filter(desired => !currentProjects.some(current => current.id === desired.id))

  const projectsToRemove = currentProjects.filter(
    current => !desiredProjects.some(desired => desired.id === current.id),
  )

  // If no changes in projects, do nothing
  if (projectsToAdd.length === 0 && projectsToRemove.length === 0) {
    return
  }

  const projectErrors: ProjectUpdateError[] = []
  const projectPromises: Array<Promise<void>> = []

  // Process additions individually using commitUpdateIssueProjectsMutation
  for (const project of projectsToAdd) {
    const promise = new Promise<void>(resolve => {
      commitUpdateIssueProjectsMutation({
        environment: environment as Environment,
        projectId: project.id,
        issueId,
        onCompleted: () => {
          resolve()
        },
        onError: (error: Error) => {
          projectErrors.push({
            projectId: project.id,
            projectTitle: project.title,
            operation: 'add',
            error: error.message,
          })
          resolve() // Resolve anyway to continue with other projects
        },
      })
    })
    projectPromises.push(promise)
  }

  // Process removals individually - we need to find the item IDs from currentProjectItems,
  for (const project of projectsToRemove) {
    const projectItem = currentProjectItems.find(item => item.project.id === project.id)
    if (!projectItem) {
      // This shouldn't happen, but if it does, log it and continue
      projectErrors.push({
        projectId: project.id,
        projectTitle: project.title,
        operation: 'remove',
        error: 'Project item not found',
      })
      continue
    }

    // For removal, we need a different approach since commitDeleteIssueProjectsMutation
    // requires connectionId and is designed for UI contexts.
    // Instead, we'll use a simple GraphQL mutation to remove the item.
    const promise = new Promise<void>(resolve => {
      commitMutation(environment, {
        mutation: graphql`
          mutation updateIssueMutationDeleteProjectMutation($input: DeleteProjectV2ItemInput!) {
            deleteProjectV2Item(input: $input) {
              deletedItemId
            }
          }
        `,
        variables: {
          input: {
            itemId: projectItem.id,
            projectId: project.id,
          },
        },
        onCompleted: () => {
          resolve()
        },
        onError: (error: Error) => {
          projectErrors.push({
            projectId: project.id,
            projectTitle: project.title,
            operation: 'remove',
            error: error.message,
          })
          resolve() // Resolve anyway to continue with other projects
        },
      })
    })
    projectPromises.push(promise)
  }

  // Wait for all project operations to complete
  await Promise.all(projectPromises)

  // If there were any errors, throw an error with details
  if (projectErrors.length > 0) {
    const errorMessage = `Failed to update ${projectErrors.length} project(s): ${projectErrors
      .map(err => `${err.operation} "${err.projectTitle}" (${err.error})`)
      .join(', ')}`

    interface ProjectUpdateErrorWithDetails extends Error {
      projectErrors: ProjectUpdateError[]
      detailedMessage: string
    }

    const error = new Error('Unable to update issue projects') as ProjectUpdateErrorWithDetails
    error.projectErrors = projectErrors
    error.detailedMessage = errorMessage
    throw error
  }
}
