import {useQuery, useQueryClient} from '@github-ui/react-query'
import {useParams} from '@github-ui/react-router'
import {useLoopsService} from '../../contexts/LoopsServiceProvider'
import {dummyPipelines} from '../../example-loops/dummy-pipelines'
import type {Loop} from '../../types/app'
import {draftVersion} from '../../utils/versions'
import {useLoopsStateLens} from '../../contexts/LoopsStateProvider'

export const LOOP_QUERY_KEY = 'loop'

/**
 * Hook to generate a loop query key that includes shareID from URL params
 * Query key format: [LOOP_QUERY_KEY, loopID, version] or [SHARED_LOOP_QUERY_KEY, shareID]
 */
export function getLoopQueryKey(loopID: string, version: string) {
  return [LOOP_QUERY_KEY, loopID, version]
}

/**
 * Hook to fetch loop data by ID using react-query. When the loop is updated via cache write or re-querying the data,
 * components will automatically re-render with the new data.
 *
 * If you only need to access the loop in a callback function, consider using `useGetLoop` instead to avoid unnecessary re-renders.
 *
 * @param version Loop version to query, defaults to 'draft'. Generally speaking you won't need to pass anything here.
 * @param selector Optional selector function to transform the loop data.
 *                 React Query will skip re-rendering if the previous result of a selector is equal to the new result.
 */
export function useLoop<T = Loop | null>(selector?: (pipeline: Loop | undefined | null) => T, version?: string) {
  const {loopID} = useParams<{loopID?: string}>()
  const service = useLoopsService()
  const queryClient = useQueryClient()
  const selectedVersion = useLoopsStateLens(l => l?.version)

  // Default to draft version if no version is provided
  const versionToFetch = version || selectedVersion || draftVersion

  // Generate dynamic query key based on whether it's a shared loop or regular loop
  const queryKey = [LOOP_QUERY_KEY, loopID, versionToFetch]

  return useQuery({
    // show the previous version of the loop until the new version is fetched
    placeholderData: previousLoop => previousLoop,
    queryKey,
    queryFn: async () => {
      if (!loopID) return null

      // Check dummy pipelines first
      const dummyLoop = dummyPipelines.find(p => p.id === loopID) ?? null
      if (dummyLoop) {
        return dummyLoop as Loop
      }

      const result = await service.getLoop(loopID, versionToFetch)

      if (!result || !result.success) return null

      // set cache data for specific version if we fetched 'draft' or 'latest'
      if (result.data.version && result.data.version !== versionToFetch) {
        queryClient.setQueryData(getLoopQueryKey(result.data.id, result.data.version), result.data)
      }

      return result.data
    },
    enabled: !!loopID,
    ...(selector && {select: selector}),
    staleTime: 5 * 60 * 1000, // 5 minutes
  })
}
