import {isFeatureEnabled} from '@github-ui/feature-flags'

export function isReactNodesEnabled() {
  return isFeatureEnabled('copilot_pipes_react_nodes')
}

export function isGitHubGraphQLNodesEnabled() {
  return isFeatureEnabled('copilot_pipes_github_graphql_nodes')
}

export function isPipelineNodesEnabled() {
  return isFeatureEnabled('copilot_pipes_pipeline_nodes')
}

export function isPostStaffShipFeaturesEnabled() {
  return isFeatureEnabled('copilot_loops_post_staff_ship_features')
}
