const GLOBAL_TOGGLE_EVENT = 'session-global-toggle'

export function TaskViewWrapper() {
  return (
    <ConsecutiveCAPI401sProvider>
      <ContentPreviewProvider>
        <TaskView />
      </ContentPreviewProvider>
    </ConsecutiveCAPI401sProvider>
  )
}

function TaskView() {
  const {pullID} = useParams<{pullID: string}>()
  const {sessionsPollingInterval, pullRequestsMap, tasks} = useAppPayload<MissionControlAppPayload>()
  const [searchParams] = useSearchParams()
  const isContentPreviewOpen = useContentPreviewOpen()
  const {openPreviewPane, closePreviewPane, openItem, updateItem} = useContentPreview()
  const buttonRef = useNavigableRef<HTMLButtonElement>()

  // pullID is required for this component to be rendered but useParams can return undefined
  if (!pullID) {
    throw new Error('pullID is required')
  }

  // Assert that pullID is a valid number
  const pullIdNum = parseInt(pullID, 10)
  if (isNaN(pullIdNum) || pullIdNum <= 0) {
    throw new Error(`Invalid pullID: ${pullID}`)
  }

  const {
    data: sessionsData,
    isError: sessionsIsError,
    timedOut: sessionsTimedOut,
  } = useSessions({
    pullId: pullIdNum,
    // TODO: We may want to pass initial sessions here from a payload if we decide to server render the task view
    initialData: undefined,
    sessionsPollingInterval,
  })

  const urlSessionId = searchParams.get('session_id')

  // Determine which session should be expanded by default
  const getDefaultOpenState = useCallback(
    (sessionId: string, index: number) => {
      if (urlSessionId) {
        // If a specific session ID is provided in URL, expand that session
        return sessionId === urlSessionId
      }
      // Otherwise, expand the most recent session (first in the sorted array)
      return index === 0
    },
    [urlSessionId],
  )

  function PreviewPaneButton() {
    return (
      !isContentPreviewOpen && (
        <IconButton
          icon={SidebarExpandIcon}
          aria-label="Open workbench"
          onClick={() => {
            openPreviewPane()
          }}
          ref={buttonRef}
        />
      )
    )
  }

  const pull = pullRequestsMap[pullIdNum]
  const currentUserCanPush = tasks.find(task => task.resource_id === pullIdNum)?.current_user_can_push ?? false

  useEffect(() => {
    const diffs = pull?.diffs ?? []
    if (diffs.length > 0) {
      // TODO: Actually use real id here and not fake data
      const taskDiffItem = makeTaskDiffItem(diffs, String(pullID))
      updateItem(taskDiffItem)
      openItem(taskDiffItem.id)
      openPreviewPane()
    }
  }, [pull, updateItem, openItem, openPreviewPane, pullID])

  const manager = useChatManager()
  const ref = useNavigableRef<HTMLTextAreaElement>()

  const setContentPreviewPaneOpen = useCallback(
    (open: boolean) => {
      if (open) {
        openPreviewPane()
      } else {
        closePreviewPane()
      }
    },
    [openPreviewPane, closePreviewPane],
  )

  useEffect(() => {
    // Set the title of the page
    // TODO: Add more descriptive Task metadata to page title based
    setTitle('Task · GitHub Copilot')
  }, [])

  useEffect(() => {
    // clear out the thread on mount
    manager.selectThread(null, {includeThreads: false, clearTopic: true})
  }, [manager])

  const {ssoOrganizations} = useChatState()
  const allProtectedOrgs = ssoOrganizations.map(org => org.login)

  useEffect(() => {
    const cacheKey = 'PROTECTED_ORGS'
    const prevOrgs = sessionStorage.getItem(cacheKey)

    if (JSON.stringify(allProtectedOrgs) !== prevOrgs) {
      const tokenProvider = new AgentSessionsTokenProvider()
      tokenProvider.removeLocalStorageAuthToken()
      sessionStorage.setItem(cacheKey, JSON.stringify(allProtectedOrgs))
    }
  }, [allProtectedOrgs])

  // TODO: Flesh out loading, error, and empty states
  return !sessionsData ? (
    <p>Loading...</p>
  ) : sessionsIsError && sessionsTimedOut ? (
    <p>Error</p>
  ) : !sessionsData.length ? (
    <p>Empty</p>
  ) : (
    <PacerLayout mainColumn="left" data-hpc secondaryColumnState={[isContentPreviewOpen, setContentPreviewPaneOpen]}>
      <PacerLayout.Header>
        <Stack direction="horizontal" align="center" justify="space-between" className="flex-1">
          <Breadcrumbs>
            <Breadcrumbs.Item href="/copilot/agents">Tasks</Breadcrumbs.Item>
            <Breadcrumbs.ItemWithMenu
              menuOverlay={
                <ActionMenu.Overlay align="end">
                  {/* TODO: Reuse the TaskNav ActionList here from the left nav once it's complete */}
                  <ActionList>
                    <ActionList.Item as="a" href="/tasks">
                      Task A
                    </ActionList.Item>
                    <ActionList.Item as="a" href="/tasks/123">
                      Task B
                    </ActionList.Item>
                  </ActionList>
                </ActionMenu.Overlay>
              }
            >
              <span>{pull?.title ?? 'Error loading data'}</span>
            </Breadcrumbs.ItemWithMenu>
          </Breadcrumbs>
          <PreviewPaneButton />
        </Stack>
      </PacerLayout.Header>
      <PacerLayout.Sidebar>
        <CopilotNavigationWithContext />
      </PacerLayout.Sidebar>
      <PacerLayout.ColumnLeft>
        <div className="p-3">
          {sessionsData.map((session, index) => (
            <SessionContextProvider key={session.id} session={session}>
              <Session
                nwo={pull?.repository_nwo}
                currentUserCanPush={currentUserCanPush}
                defaultOpen={getDefaultOpenState(session.id, index)}
              />
            </SessionContextProvider>
          ))}
        </div>
      </PacerLayout.ColumnLeft>
      <PacerLayout.ColumnRight>
        <ContentPreview returnFocusRef={ref} />
      </PacerLayout.ColumnRight>
    </PacerLayout>
  )
}

function Session({
  nwo,
  currentUserCanPush,
  defaultOpen = false,
}: {
  nwo: string | undefined
  currentUserCanPush: boolean
  defaultOpen?: boolean
}) {
  const {getDetailsProps, setOpen} = useDetails({defaultOpen})
  const {logsPollingInterval} = useAppPayload<MissionControlAppPayload>()
  const sessionDetailsRef = useRef<HTMLDetailsElement>(null)
  const toolInstanceRef = useRef({})

  const handlerRef = useRef<((event: Event) => void) | null>(null)

  handlerRef.current = (event: Event) => {
    const customEvent = event as CustomEvent<{expand: boolean; excludeInstance: object}>
    if (customEvent.detail.excludeInstance !== toolInstanceRef.current) {
      setOpen(customEvent.detail.expand)
    }
  }

  // Combined effect for setting up event listeners
  useEffect(() => {
    // Set up global expand/collapse event listener
    const globalToggleHandler = (event: Event) => {
      handlerRef.current?.(event)
    }

    document.addEventListener(GLOBAL_TOGGLE_EVENT, globalToggleHandler)

    // Set up session details toggle event listener
    const sessionElement = sessionDetailsRef.current
    let sessionToggleHandler: ((event: Event) => void) | null = null

    if (sessionElement) {
      sessionToggleHandler = (event: Event) => {
        // If the toggle event originated from a nested details element (not this session's direct toggle)
        if (event.target !== sessionElement) {
          event.stopPropagation()
        }
      }

      sessionElement.addEventListener('toggle', sessionToggleHandler, true) // Use capture phase
    }

    return () => {
      document.removeEventListener(GLOBAL_TOGGLE_EVENT, globalToggleHandler)
      if (sessionElement && sessionToggleHandler) {
        sessionElement.removeEventListener('toggle', sessionToggleHandler, true)
      }
    }
  }, [])

  const handleModifierClick = (expand: boolean) => {
    // Set this tool to the desired state
    setOpen(expand)

    // Dispatch event to all other tools
    const event = new CustomEvent(GLOBAL_TOGGLE_EVENT, {
      detail: {expand, excludeInstance: toolInstanceRef.current},
    })
    document.dispatchEvent(event)
  }

  return (
    <Details
      {...getDetailsProps()}
      ref={sessionDetailsRef}
      className={`${styles.detailsContainer} border rounded overflow-hidden bgColor-default`}
    >
      <SessionHeader
        nwo={nwo}
        currentUserCanPush={currentUserCanPush}
        isCollapsed={!getDetailsProps().open}
        onModifierClick={handleModifierClick}
      />
      {/* Temporary default until backend change is in */}
      <SessionLogs logsPollingInterval={logsPollingInterval ?? 3000} />
    </Details>
  )
}

function SessionHeader({
  nwo,
  currentUserCanPush,
  isCollapsed,
  onModifierClick,
}: {
  nwo: string | undefined
  currentUserCanPush: boolean
  isCollapsed: boolean
  onModifierClick: (expand: boolean) => void
}) {
  const {session} = useSessionContext()
  const workflowLink = generateWorkflowRunLink(nwo ?? null, session.workflow_run_id)

  const handleClick = (event: React.MouseEvent) => {
    // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
    if ((event.altKey || event.metaKey) && onModifierClick) {
      event.preventDefault()
      event.stopPropagation()
      // If currently collapsed, expand all; if expanded, collapse all
      onModifierClick(!!isCollapsed)
      return false // Prevent further event handling
    }
  }

  return (
    <Button
      as="summary"
      block
      alignContent="start"
      aria-expanded={!isCollapsed}
      aria-labelledby="session-header-title"
      leadingVisual={isCollapsed ? <ChevronRightIcon /> : <ChevronDownIcon />}
      // Click handler only applies to modifier key
      // Otherwise the default behaviour of the `<summary>` element will handle the click
      onClick={handleClick}
    >
      <Stack direction="horizontal" gap="spacious" wrap="wrap" justify="space-between" align={'center'}>
        {/* Left side - Session name and basic info */}
        <Stack direction="horizontal" gap="spacious" wrap="wrap" className="flex-items-center">
          <span className="overflow-hidden text-truncate">{session.name}</span>

          {/* Status */}
          <Stack gap="none" direction="horizontal" className="flex-items-center">
            {getSessionStatusIcon(session.state)}
            <span className="ml-2 text-semibold">{getReadableSessionState(session.state)}</span>
          </Stack>

          {/* Duration */}
          {session.state !== 'queued' && (
            <Stack gap="none" direction="horizontal" className="flex-items-center">
              <span className="text-small fgColor-muted mr-1">Duration:</span>
              <span role="timer" className="text-semibold">
                <SessionElapsedTime
                  createdAt={session.created_at}
                  completedAt={session.completed_at}
                  state={session.state}
                />
              </span>
            </Stack>
          )}
        </Stack>

        {/* Right side - Actions */}
        {/* TODO: Nesting controls (i.e. these buttons within the larger summary/details header) causes a serious a11y error.
         ** Let's clarify and refine this UI with designers going forward before release.
         */}
        <Stack direction="horizontal" gap="condensed" className="flex-items-center" align={'center'}>
          <SessionStopButton nwo={nwo} currentUserCanPush={currentUserCanPush} />
          {workflowLink && (
            <ActionMenu>
              <ActionMenu.Anchor>
                <IconButton icon={KebabHorizontalIcon} aria-label="Open menu" />
              </ActionMenu.Anchor>
              <ActionMenu.Overlay>
                <ActionList>
                  <ActionList.LinkItem href={workflowLink}>View verbose logs</ActionList.LinkItem>
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          )}
        </Stack>
      </Stack>
    </Button>
  )
}

try{ TaskViewWrapper.displayName ||= 'TaskViewWrapper' } catch {}
try{ TaskView.displayName ||= 'TaskView' } catch {}
try{ PreviewPaneButton.displayName ||= 'PreviewPaneButton' } catch {}
try{ Session.displayName ||= 'Session' } catch {}
try{ SessionHeader.displayName ||= 'SessionHeader' } catch {}