import {RunningDisplay} from './RunningDisplay'
import {ErrorDisplay} from './ErrorDisplay'
import {OutputDisplay} from './OutputDisplay'
import {ExecuteButton} from '../controls/ExecuteButton'
import type {NodeValue} from '../../types/app'
import styles from './ExecutionView.module.css'
import type {ReactNode} from 'react'
import {sendEvent} from '@github-ui/hydro-analytics'
import {SyncIcon} from '@primer/octicons-react'

const EMPTY_ERRORS: string[] = []

interface ExecutionViewProps {
  outputNodeExists: boolean
  isRunning: boolean
  nodeValue: NodeValue
  nodeError: string | null
  validationErrors?: string[]
  additionalActions?: ReactNode
  onRun: () => void
  onStop: () => void
}

/**
 * Presentational component that shows the various states related to an execution of a loop:
 * - running
 * - validation errors
 * - execution errors
 * - output
 * - waiting
 */
export function ExecutionView({
  outputNodeExists,
  isRunning,
  nodeValue,
  nodeError,
  validationErrors = EMPTY_ERRORS,
  additionalActions,
  onRun,
  onStop,
}: ExecutionViewProps) {
  return (
    <>
      {!outputNodeExists ? (
        <p>No output nodes found in this loop.</p>
      ) : isRunning && !nodeValue ? (
        <RunningDisplay
          isRunning={isRunning}
          messages={{
            running: 'Running the loop...',
            waiting: 'Waiting...',
          }}
        />
      ) : validationErrors.length > 0 ? (
        <ErrorDisplay
          errors={validationErrors}
          title="Oops, this loop is configured incorrectly"
          additionalActions={additionalActions}
        />
      ) : nodeError ? (
        <ErrorDisplay
          errors={[nodeError]}
          title="Oops, there was an error running this loop"
          additionalActions={additionalActions}
        />
      ) : nodeValue ? (
        <OutputDisplay isRunning={isRunning} nodeValue={nodeValue} />
      ) : (
        <div className={styles.emptyState}>
          <div className={styles.emptyStateText}>
            <span className={styles.emptyStateTitle}>No output yet</span>
            <span>Run this loop to generate output</span>
          </div>
          <ExecuteButton
            onClick={() => {
              onRun()
              sendEvent('node_action.select', {target: 'PANEL_NODE_EMPTY_STATE_RUN', mode: 'loops'})
            }}
            onStop={() => {
              onStop()
              sendEvent('node_action.select', {target: 'PANEL_NODE_EMPTY_STATE_STOP', mode: 'loops'})
            }}
            isLoading={isRunning}
            value={nodeValue}
            variant="default"
            leadingVisual={<SyncIcon />}
          />
        </div>
      )}
    </>
  )
}

try{ ExecutionView.displayName ||= 'ExecutionView' } catch {}