import {useChatState} from '@github-ui/copilot-chat/CopilotChatContext'
import type {CopilotSpace, CopilotSpaceId, IndexCopilotSpace} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
import {getCopilotSpacePath} from '@github-ui/copilot-chat/utils/custom-copilots-helpers'
import {CreateSpaceButton} from '@github-ui/copilot-spaces/components/CreateSpaceButton'
import {useDeleteCopilotSpace} from '@github-ui/copilot-spaces/hooks'
import type {CopilotSpacesConfigPayload} from '@github-ui/copilot-spaces/types'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {sendEvent} from '@github-ui/hydro-analytics'
import {ContentView} from '@github-ui/pacer/ContentView'
import {ListBlock} from '@github-ui/pacer/ListBlock'
import {matchesCommonSearch} from '@github-ui/pacer/search-utils'
import {SearchInput} from '@github-ui/pacer/SearchInput'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import {SingleSignOnBanner} from '@github-ui/single-sign-on-banner'
import {AlertIcon, LockIcon, OrganizationIcon, PeopleIcon, PersonIcon} from '@primer/octicons-react'
import {Flash} from '@primer/react'
import {clsx} from 'clsx'
import {useEffect, useMemo, useState} from 'react'

import {getVisibilityText} from '../../../../utils/visibility-helpers'
import {ErrorFallback} from '../../../ErrorFallback'
import {CopilotSpacesMenu} from '../../SpaceMenu'
import styles from './SpacesView.module.css'

const title = 'Spaces'
const description = 'A persistent space that remembers your code, files, and preferences across conversations.'

export interface SpacesViewProps {
  copilotSpaces: IndexCopilotSpace[] | undefined
}

interface SpacesListProps {
  spaces: IndexCopilotSpace[] | undefined
  starredSpaces: IndexCopilotSpace[] | undefined
  isLoading: boolean
  onDelete: (space: CopilotSpaceId) => Promise<void>
  onSpaceClick: () => void
  searchQuery: string
}

interface SpacesListItemProps {
  copilotSpace: IndexCopilotSpace
  onDelete: () => Promise<void>
  onClick: () => void
}

function SpacesListItem({copilotSpace, onDelete, onClick}: SpacesListItemProps) {
  const OwnerIcon = copilotSpace.ownerIsOrg ? OrganizationIcon : PersonIcon
  const visibilityText = getVisibilityText(
    copilotSpace.visibility,
    copilotSpace.baseRole,
    copilotFeatureFlags.copilotSpacesReadAccessToUserOwnedSpaces ? copilotSpace.collaborative : false,
  )
  const VisibilityIcon = visibilityText === 'Shared' ? PeopleIcon : LockIcon
  const showSpacesMenu = copilotSpace.adminable || copilotSpace.editable

  return (
    <ListBlock.Item href={getCopilotSpacePath(copilotSpace)} onClick={onClick}>
      <ListBlock.Item.Title>{copilotSpace.name}</ListBlock.Item.Title>
      <ListBlock.Item.Description>
        <div className={styles.description}>{copilotSpace.description}</div>
      </ListBlock.Item.Description>
      <ListBlock.Item.Metadata>
        <div className={styles.metadata}>
          <span className={styles.metadataItem}>
            <OwnerIcon size={16} />
            {copilotSpace.owner}
          </span>
          <span className={styles.metadataItem}>
            <VisibilityIcon size={16} />
            {visibilityText}
          </span>
        </div>
      </ListBlock.Item.Metadata>
      {showSpacesMenu && (
        <ListBlock.Item.Actions>
          <CopilotSpacesMenu copilot={copilotSpace} onDelete={onDelete} />
        </ListBlock.Item.Actions>
      )}
    </ListBlock.Item>
  )
}

const shouldShowInSharedTab = (copilotSpace: CopilotSpace | IndexCopilotSpace) =>
  copilotSpace.shared && copilotSpace.collaborative

function SpacesList({spaces, starredSpaces, isLoading, onDelete, onSpaceClick, searchQuery}: SpacesListProps) {
  const [activeTab, setActiveTab] = useState<'starred' | 'personal' | 'org' | 'shared'>('personal')
  const hasStarred = starredSpaces && starredSpaces.length > 0
  const sharedByMeTabEnabled = copilotFeatureFlags.copilotSpacesReadAccessToUserOwnedSpaces

  const {
    copilotSpacesConfig: {userHasOrgs},
  } = useAppPayload<CopilotSpacesConfigPayload>()

  useEffect(() => {
    if (hasStarred) {
      setActiveTab('starred')
    }
  }, [hasStarred])

  // Apply combined filtering
  const filteredSpaces = useMemo(() => {
    if (!spaces) return []

    return spaces.filter(space => {
      // Filter by tab first
      const matchesTab =
        (activeTab === 'starred' && space.starred) ||
        (activeTab === 'personal' && !space.ownerIsOrg && !space.shared) ||
        (activeTab === 'org' && space.ownerIsOrg) ||
        (sharedByMeTabEnabled ? activeTab === 'shared' && shouldShowInSharedTab(space) : false)

      if (!matchesTab) return false

      // Then filter by search query
      return matchesCommonSearch(space, searchQuery)
    })
  }, [spaces, activeTab, searchQuery, sharedByMeTabEnabled])

  // Calculate tab counts
  const {personalSpacesCount, orgSpacesCount, starredSpacesCount, sharedSpacesCount} = useMemo(() => {
    if (!spaces) return {personalSpacesCount: 0, orgSpacesCount: 0, starredSpacesCount: 0, sharedSpacesCount: 0}

    // Apply search filter first
    const filtered = searchQuery.trim() ? spaces.filter(space => matchesCommonSearch(space, searchQuery)) : spaces

    return {
      personalSpacesCount: filtered.filter(space => !space.ownerIsOrg && !space.shared).length,
      orgSpacesCount: filtered.filter(space => space.ownerIsOrg).length,
      starredSpacesCount: filtered.filter(space => space.starred).length,
      sharedSpacesCount: sharedByMeTabEnabled ? filtered.filter(shouldShowInSharedTab).length : 0,
    }
  }, [spaces, searchQuery, sharedByMeTabEnabled])

  const hasNoSpaces = spaces?.length === 0 && !isLoading
  const hasNoMatchingSpaces = spaces && spaces.length > 0 && filteredSpaces?.length === 0 && !isLoading
  const userHasSharedSpaces = sharedByMeTabEnabled && sharedSpacesCount > 0

  return (
    <ListBlock>
      <ListBlock.Header>
        {/* This really needs a loading state*/}
        <div role="tablist" aria-label="Filter spaces" className={styles.filterButtons}>
          {hasStarred && (
            <button
              onClick={() => setActiveTab('starred')}
              role="tab"
              aria-selected={activeTab === 'starred'}
              aria-controls="spaces-list"
              id="starred-tab"
              className={styles.button}
            >
              Starred <span className={styles.counter}>{starredSpacesCount}</span>
            </button>
          )}
          {/* When only the 'Yours' tab is being shown, make it a span instead of a button  */}
          {userHasOrgs || hasStarred || userHasSharedSpaces ? (
            <button
              onClick={() => setActiveTab('personal')}
              role="tab"
              aria-selected={activeTab === 'personal'}
              aria-controls="spaces-list"
              id="personal-tab"
              className={styles.button}
            >
              Yours <span className={styles.counter}>{personalSpacesCount}</span>
            </button>
          ) : (
            <span id="disabled-personal-tab" role="tab" className={styles.disabledButton}>
              Yours <span className={styles.counter}>{personalSpacesCount}</span>
            </span>
          )}
          {userHasSharedSpaces && (
            <button
              onClick={() => setActiveTab('shared')}
              role="tab"
              aria-selected={activeTab === 'shared'}
              aria-controls="spaces-list"
              id="shared-with-me-tab"
              className={clsx(styles.button, styles.sharedSpacesTab)}
            >
              Shared With Me <span className={styles.counter}>{sharedSpacesCount}</span>
            </button>
          )}
          {userHasOrgs && (
            <button
              onClick={() => setActiveTab('org')}
              role="tab"
              aria-selected={activeTab === 'org'}
              aria-controls="spaces-list"
              id="org-tab"
              className={styles.button}
            >
              Organizations <span className={styles.counter}>{orgSpacesCount}</span>
            </button>
          )}
        </div>
      </ListBlock.Header>
      <ListBlock.List loading={isLoading} id="spaces-list" aria-labelledby={activeTab}>
        {hasNoSpaces ? (
          <ListBlock.EmptyState>
            <p>Set up once. Chat again and again.</p>
            <CreateSpaceButton />
          </ListBlock.EmptyState>
        ) : hasNoMatchingSpaces ? (
          <ListBlock.EmptyState>
            <p>
              {activeTab === 'starred' && 'Spaces you star will appear here.'}
              {activeTab === 'personal' && 'Spaces you create will appear here.'}
              {activeTab === 'org' && 'Spaces belonging to your organizations will appear here.'}
              {activeTab === 'shared' && 'Shared spaces will appear here.'}
            </p>
            <CreateSpaceButton />
          </ListBlock.EmptyState>
        ) : (
          filteredSpaces?.map(copilotSpace => (
            <SpacesListItem
              key={copilotSpace.owner ? `${copilotSpace.owner}/${copilotSpace.id}` : copilotSpace.id}
              copilotSpace={copilotSpace}
              onDelete={() => onDelete(copilotSpace)}
              onClick={onSpaceClick}
            />
          ))
        )}
      </ListBlock.List>
    </ListBlock>
  )
}

export function SpacesView({copilotSpaces}: SpacesViewProps) {
  const state = useChatState()
  const {ssoOrganizations} = state

  const allProtectedOrgs = ssoOrganizations.map(org => org.login)

  const [deletionError, setDeletionError] = useState<Error | null>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const isLoading = copilotSpaces === undefined

  const starredSpaces = copilotSpaces?.filter(space => space.starred)

  const {mutateAsync: deleteCustomCopilot} = useDeleteCopilotSpace()

  const handleCopilotSpaceDelete = async (item: CopilotSpaceId) => {
    try {
      await deleteCustomCopilot(item)
      setDeletionError(null)
    } catch (err) {
      setDeletionError(err instanceof Error ? err : new Error(String(err)))
    }
  }

  const handleOnClickCopilotSpace = () => {
    sendEvent('dotcom_chat.activate', {
      target: 'SPACES_VIEW_SPACE_SELECTED',
      mode: 'immersive',
    })
  }

  return (
    <ErrorBoundary fallback={<ErrorFallback regionName="Spaces" />}>
      {deletionError && (
        <Flash variant="danger">
          <AlertIcon />
          There was a problem deleting your space.
        </Flash>
      )}
      <ContentView.Container width="small">
        <ContentView.Header>
          <ContentView.Title>{title}</ContentView.Title>
          <ContentView.Description>{description}</ContentView.Description>
          <ContentView.Actions>
            <CreateSpaceButton primary />
          </ContentView.Actions>
        </ContentView.Header>

        {ssoOrganizations.length > 0 && !isFeatureEnabled('global_sso_banner') && (
          <div className={styles.banner}>
            <SingleSignOnBanner
              protectedOrgs={allProtectedOrgs}
              redirectURI={() =>
                `/search/refresh_blackbird_caches?return_to=${encodeURIComponent(window.location.href)}`
              }
            />
          </div>
        )}

        <SearchInput onSearch={setSearchQuery} />

        <ContentView.Section>
          <SpacesList
            spaces={copilotSpaces}
            starredSpaces={starredSpaces}
            isLoading={isLoading}
            onDelete={handleCopilotSpaceDelete}
            onSpaceClick={handleOnClickCopilotSpace}
            searchQuery={searchQuery}
          />
        </ContentView.Section>
      </ContentView.Container>
    </ErrorBoundary>
  )
}

try{ SpacesListItem.displayName ||= 'SpacesListItem' } catch {}
try{ SpacesList.displayName ||= 'SpacesList' } catch {}
try{ SpacesView.displayName ||= 'SpacesView' } catch {}