import type {Loop} from '../types/app'
import {LoopRunner, type GetExecutionCallback, type LoopRunnerAction} from './loop-runner'

import type {GraphQLClient} from './graphql-client'
import type {ChatCompletionsClient} from './chat-completions-client'
import type {Execution, NodeExecution} from '../types/execution'
import type {GraphQLSuccessfulResult} from '../utils/graphql'
import {removeLoopThreadId} from '../utils/loop-thread-storage'
import type {LoopsClient} from './loops-client'
import type {Result} from './result'
import {validateLoop} from './validate-loop'
import {draftVersion, latestVersion} from '../utils/versions'
import type {Version} from '../types/version'
import {sendEvent} from '@github-ui/hydro-analytics'

export class LoopsService {
  readonly #client: LoopsClient
  readonly #graphQLClient: GraphQLClient
  readonly #chatClient: ChatCompletionsClient
  readonly #activeRunners: Map<string, LoopRunner> = new Map()

  constructor(client: LoopsClient, gqlClient: GraphQLClient, chatClient: ChatCompletionsClient) {
    this.#cleanUpStorage()
    this.#client = client
    this.#graphQLClient = gqlClient
    this.#chatClient = chatClient
  }

  async getGraphQLResponse(query: string): Promise<GraphQLSuccessfulResult | undefined> {
    return this.#graphQLClient.getGraphQLResponse(query)
  }

  getLoop(loopID: string, version: string = draftVersion): Promise<Result<Loop>> {
    return this.#client.getLoop(loopID, version)
  }

  getAllLoops(): Promise<Result<Loop[]>> {
    return this.#client.listLoops()
  }

  getLoopVersions(loopID: string): Promise<Result<Version[]>> {
    return this.#client.listLoopVersions(loopID)
  }

  createLoop(loopOrId: Loop | string): Promise<Result<Loop>> {
    return this.#client.createLoop(typeof loopOrId === 'string' ? {id: loopOrId} : loopOrId)
  }

  async updateLoop(loopID: string, updateFn: (existingLoop: Loop | null) => Loop): Promise<Result<Loop>> {
    const existing = await this.#client.getLoop(loopID, draftVersion)
    if (!existing.success) {
      return existing
    }
    const toUpdate = updateFn(existing.data)
    return await this.#client.updateLoop(loopID, draftVersion, toUpdate)
  }

  async deleteLoop(loopID: string): Promise<Result<void>> {
    // clean up local storage
    removeLoopThreadId(loopID)

    return this.#client.deleteLoop(loopID)
  }

  async saveLoop(loopOrID: string | Loop): Promise<Result<Loop>> {
    const loop = typeof loopOrID === 'string' ? ({id: loopOrID} as unknown as Loop) : loopOrID
    return await this.#client.updateLoop(loop.id, latestVersion, loop)
  }

  async restoreLoopVersion(loop: Loop): Promise<Result<Loop>> {
    return await this.#client.updateLoop(loop.id, latestVersion, loop)
  }

  async revertLoop(loopID: string): Promise<Result<Loop>> {
    const existingLatest = await this.#client.getLoop(loopID, latestVersion)
    if (!existingLatest.success) {
      return existingLatest
    }
    return this.#client.updateLoop(loopID, 'draft', existingLatest.data)
  }

  getExecution(loopID: string, version: string, executionID: string): Promise<Result<Execution>> {
    return this.#client.getExecution(loopID, version, executionID)
  }

  async createExecution(
    loopID: string,
    version: string,
    previousExecution?: Partial<Execution>,
  ): Promise<Result<Execution>> {
    return this.#client.createExecution(loopID, version, previousExecution?.nodes, previousExecution?.inputValues)
  }

  updateNodeExecution(
    loopID: string,
    version: string,
    executionID: string,
    nodeID: string,
    nodeExecution: NodeExecution,
  ): Promise<Result<NodeExecution>> {
    return this.#client.updateNodeExecution(loopID, version, executionID, nodeID, nodeExecution)
  }

  async updateExecution(
    loopID: string,
    version: string,
    executionID: string,
    state: Execution,
  ): Promise<Result<Execution>> {
    const currentResult = await this.#client.getExecution(loopID, version, executionID)
    if (!currentResult.success) return currentResult

    const currentExecution = currentResult.data
    for (const [nodeID, ne] of Object.entries(state.nodes)) {
      if (
        !currentExecution.nodes[nodeID] ||
        currentExecution.nodes[nodeID].value !== ne.value ||
        currentExecution.nodes[nodeID].error !== ne.error
      ) {
        await this.#client.updateNodeExecution(loopID, version, executionID, nodeID, ne)
      }
    }
    return await this.#client.getExecution(loopID, version, executionID)
  }

  isExecutionRunning(executionID: string): boolean {
    return !!this.#activeRunners.get(executionID)
  }

  async runPipeline(
    pipeline: Loop,
    executionID: string,
    onProgress: (action: LoopRunnerAction) => void,
    onGetExecution: GetExecutionCallback,
  ): Promise<void> {
    const errors = validateLoop(pipeline)
    if (errors.length > 0) return

    const runner = new LoopRunner(pipeline, executionID, this.#graphQLClient, this.#chatClient)

    this.#activeRunners.set(executionID, runner)

    try {
      await runner.run(onProgress, onGetExecution)

      // Send Hydro analytics event for successful execution
      sendEvent('dotcom_chat.loops_execution', {
        execution_id: executionID,
        loop_id: pipeline.id,
        node_count: pipeline.nodes.length,
        status: 'success',
      })
    } catch (error) {
      // Send Hydro analytics event for failed execution
      sendEvent('dotcom_chat.loops_execution', {
        execution_id: executionID,
        loop_id: pipeline.id,
        node_count: pipeline.nodes.length,
        status: 'error',
      })

      throw error
    } finally {
      // Clean up runner reference when done
      this.#activeRunners.delete(executionID)
    }
  }

  stopPipeline(executionID: string, cancelExecution: (executionID: string) => void): void {
    const runner = this.#activeRunners.get(executionID)
    if (!runner) {
      return
    }

    runner.stop(cancelExecution)
    this.#activeRunners.delete(executionID)

    // Send Hydro analytics event for cancelled execution
    sendEvent('dotcom_chat.loops_execution', {
      execution_id: executionID,
      status: 'canceled',
    })
  }

  async shareLoop(loopID: string): Promise<Result<void>> {
    return await this.#client.shareLoop(loopID)
  }

  async unshareLoop(loopID: string): Promise<Result<void>> {
    return await this.#client.unshareLoop(loopID)
  }

  #cleanUpStorage() {
    indexedDB.deleteDatabase('copilot-pipes')
  }
}
