import {Button} from '@primer/react'
import {useChatMessageLoopReference} from './use-chat-message-loop-reference'
import {LoopBlockContent} from './LoopBlockContent'
import {sanitizeLoop} from '../../utils/loops'
import {useUpdateLoop} from '../../hooks/mutations/use-update-loop'
import {arePipelinesEqual} from '../../utils/pipeline-comparisons'
import {useLoop} from '../../hooks/queries/use-loop'

export interface LoopBlockProps {
  isStreaming?: boolean
}

export function LoopBlock({isStreaming}: LoopBlockProps) {
  const loopFromChat = useChatMessageLoopReference()
  const {mutate: updateLoop} = useUpdateLoop()
  const {data: loop} = useLoop()

  const handleRestoreLoop = () => {
    if (!loop || !loopFromChat) return

    const newLoop = sanitizeLoop({...loopFromChat, id: loop.id}, [])
    updateLoop({loopID: loop.id, updateFn: () => newLoop})
  }

  const shouldShowRestoreButton = loop && !isStreaming && !arePipelinesEqual(loop, loopFromChat)

  const restoreButton = shouldShowRestoreButton ? (
    <Button variant="invisible" onClick={handleRestoreLoop}>
      Restore
    </Button>
  ) : null

  return <LoopBlockContent loop={loopFromChat} headerButton={restoreButton} isStreaming={isStreaming} />
}

try{ LoopBlock.displayName ||= 'LoopBlock' } catch {}