import {BlockedIcon} from '@primer/octicons-react'
import {CounterLabel, Token} from '@primer/react'
import {clsx} from 'clsx'
import React from 'react'

import styles from './IssueTree.module.css'

const TreeContext = React.createContext<{
  hasTrailingVisuals: boolean | undefined
}>({
  hasTrailingVisuals: undefined,
})

const ItemContext = React.createContext<{
  level: number
}>({
  level: 0,
})

type TreeProps = React.PropsWithChildren<{
  subIssueCount: number
  subIssueHeaderText?: string
  hasTrailingVisuals?: boolean
}>

function Tree({subIssueCount, subIssueHeaderText = 'Sub-issues', hasTrailingVisuals = false, children}: TreeProps) {
  const childrenArray = React.Children.toArray(children)
  const rootItem = childrenArray.find(child => React.isValidElement(child) && child.type === TreeRootItem)
  const items = childrenArray.filter(child => React.isValidElement(child) && child.type === TreeItem)

  const providerProps = React.useMemo(() => ({hasTrailingVisuals}), [hasTrailingVisuals])

  return (
    <TreeContext.Provider value={providerProps}>
      <div className={styles.container} data-has-trailing-visual={hasTrailingVisuals ? true : undefined}>
        {rootItem}

        {items.length > 0 && (
          <>
            <div className={styles.subHeader}>
              {subIssueHeaderText}
              <CounterLabel>{subIssueCount}</CounterLabel>
            </div>
            <ul role="tree" className={styles.tree}>
              {items}
            </ul>
          </>
        )}
      </div>
    </TreeContext.Provider>
  )
}

type TreeRootItemProps = TreeItemContentProps

function TreeRootItem(props: TreeRootItemProps) {
  const providerProps = React.useMemo(() => ({level: 0}), [])

  return (
    <ItemContext.Provider value={providerProps}>
      <div className={clsx(styles.item, styles.rootItem)}>
        <TreeItemContent {...props} />
      </div>
    </ItemContext.Provider>
  )
}

type TreeItemProps = React.PropsWithChildren<TreeItemContentProps>
function TreeItem({children, ...props}: TreeItemProps) {
  const childrenArray = React.Children.toArray(children)
  const nestedItems = childrenArray.filter(child => React.isValidElement(child) && child.type === TreeItem)
  const contentChildren = childrenArray.filter(child => !(React.isValidElement(child) && child.type === TreeItem))

  const {level} = React.useContext(ItemContext)
  const providerProps = React.useMemo(() => ({level: level + 1}), [level])

  return (
    <ItemContext.Provider value={providerProps}>
      <li role="treeitem" aria-selected="false" className={styles.item}>
        <TreeItemContent {...props}>{contentChildren}</TreeItemContent>
        {nestedItems.length > 0 && (
          <ul role="group" className={styles.tree}>
            {nestedItems}
          </ul>
        )}
      </li>
    </ItemContext.Provider>
  )
}

type TreeItemContentProps = {
  leadingVisual?: React.ReactNode
  title: string
  description?: React.ReactNode
  trailingBadge?: React.ReactNode
  trailingVisual?: React.ReactNode
  href?: string
  onClick?: (event: React.MouseEvent) => void
  blockedBy?: string[]
}
function TreeItemContent({
  leadingVisual,
  title,
  description,
  trailingBadge,
  trailingVisual,
  href,
  onClick,
  blockedBy,
}: TreeItemContentProps) {
  const {level} = React.useContext(ItemContext)
  const {hasTrailingVisuals} = React.useContext(TreeContext)

  const titleElementType = React.useMemo(() => {
    if (href) return 'a'
    if (onClick) return 'button'
    return 'div'
  }, [href, onClick])

  return (
    <>
      <div className={styles.grid} style={{'--level': level}} data-has-onclick={onClick ? true : undefined}>
        {level > 0 && <div className={styles.spacer} />}
        <div className={styles.leadingVisual}>{leadingVisual}</div>
        <div className={styles.content}>
          {React.createElement(
            titleElementType,
            {
              className: styles.title,
              href,
              onClick,
            },
            title,
          )}
          {trailingBadge}
        </div>
        {(description != null || blockedBy != null) && (
          <div className={styles.description}>
            {blockedBy && <IssueDependencies dependencyType="Blocked by" items={blockedBy} />}
            {description}
          </div>
        )}
        {hasTrailingVisuals && <div className={styles.trailingVisual}>{trailingVisual}</div>}
      </div>
    </>
  )
}

interface IssueDependenciesProps {
  dependencyType: 'Blocked by'
  items: string[]
}
function IssueDependencies({dependencyType, items}: IssueDependenciesProps) {
  if (items.length === 0) return null

  return (
    <Token
      size="medium"
      className="mr-2"
      leadingVisual={() => <BlockedIcon className="fgColor-danger" size={14} />}
      text={
        items.length > 1 ? (
          <>
            {dependencyType} {items.length}
          </>
        ) : (
          <>
            {dependencyType}: {items[0]}
          </>
        )
      }
    />
  )
}

export const IssueTree = Object.assign(Tree, {
  RootItem: TreeRootItem,
  Item: TreeItem,
})

try{ Tree.displayName ||= 'Tree' } catch {}
try{ TreeRootItem.displayName ||= 'TreeRootItem' } catch {}
try{ TreeItem.displayName ||= 'TreeItem' } catch {}
try{ TreeItemContent.displayName ||= 'TreeItemContent' } catch {}
try{ IssueDependencies.displayName ||= 'IssueDependencies' } catch {}
try{ IssueTree.displayName ||= 'IssueTree' } catch {}