import {reactFetchJSON} from '@github-ui/verified-fetch'
import {CopilotAuthTokenProvider} from '@github-ui/copilot-auth-token'
import {validateGraphQL} from '../utils/graphql'

export class GraphQLClient {
  readonly #graphqlApiUrl: string
  readonly #copilotAuthTokenProvider: CopilotAuthTokenProvider

  constructor(graphqlApiUrl: string, ssoOrgIds: string[]) {
    this.#graphqlApiUrl = graphqlApiUrl
    this.#copilotAuthTokenProvider = new CopilotAuthTokenProvider(ssoOrgIds)
  }

  async getGraphQLResponse(query: string, signal?: AbortSignal) {
    const token = await this.#copilotAuthTokenProvider.getAuthToken()

    const headers = {
      ['X-Copilot-Api-Token']: token.value,
    }

    const body = {
      query,
    }

    const response = await reactFetchJSON(this.#graphqlApiUrl, {
      method: 'POST',
      body,
      headers,
      signal,
    })

    if (response.ok) {
      const responseJson = await response.json()
      const requestId = response.headers.get('X-Github-Request-Id') || ''
      if (validateGraphQL(responseJson, requestId)) {
        return responseJson
      }
    } else {
      throw new Error('Failed to get GraphQL response.')
    }
  }
}
