import {AlertIcon, BeakerIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import styles from './ErrorDisplay.module.css'
import {useIsReadonly} from '../../hooks/use-is-readonly'
import type {ReactNode} from 'react'

interface ErrorDisplayProps {
  additionalActions?: ReactNode
  title?: string
  errors: string[]
  onFixErrorClick?: () => void
}

export function ErrorDisplay({additionalActions, errors, onFixErrorClick, title}: ErrorDisplayProps) {
  const {isReadonly} = useIsReadonly()

  return (
    <div className={styles.errorContainer}>
      <AlertIcon className={styles.errorIcon} size={'medium'} />
      <div className={styles.errorNotice}>
        <h2 className={styles.errorTitle}>{title}</h2>
        {errors.map(error => (
          <p key={error} className={styles.errorText}>
            {error}
          </p>
        ))}
      </div>
      <div className={styles.errorActions}>
        {additionalActions}
        {!isReadonly && onFixErrorClick && (
          <Button leadingVisual={BeakerIcon} onClick={onFixErrorClick}>
            Try to fix it
          </Button>
        )}
      </div>
    </div>
  )
}

try{ ErrorDisplay.displayName ||= 'ErrorDisplay' } catch {}