import type {Node, NodeValue, Loop, LoopGraph} from '../types/app'
import {getOutputNodes, getLoopGraph} from '../utils/loops'
import {replaceVariablesInNode} from './node-processor'
import type {ChatCompletionsClient} from './chat-completions-client'
import type {GraphQLClient} from './graphql-client'
import {NodeRunner} from './node-runner'
import type {Execution} from '../types/execution'
import type {Result} from './result'
import {draftVersion} from '../utils/versions'

// Actions that LoopRunner dispatches - execution-related actions
export type LoopRunnerAction =
  | {type: 'UPDATE_NODE_VALUE'; nodeID: string; value: NodeValue}
  | {type: 'UPDATE_NODE_VALUE_PARTIAL'; nodeID: string; value: NodeValue}
  | {type: 'UPDATE_NODE_ERROR'; nodeID: string; error: string}
  | {type: 'SET_RUNNING'; nodeID: string}
  | {type: 'CANCEL_EXECUTION'}

export type GetExecutionCallback = (
  loopID: string,
  loopVersion: string,
  executionID: string,
) => Promise<Result<Execution>>

type ProgressCallback = (action: LoopRunnerAction) => void

export class LoopRunner {
  readonly #graphQLClient: GraphQLClient
  readonly #chatClient: ChatCompletionsClient

  readonly #loop: Loop
  readonly #executionID: string
  readonly #graph: LoopGraph
  readonly #nodePromises: Map<string, Promise<NodeValue>>
  readonly #abortController: AbortController

  constructor(loop: Loop, executionID: string, gqlClient: GraphQLClient, chatClient: ChatCompletionsClient) {
    this.#graphQLClient = gqlClient
    this.#chatClient = chatClient

    this.#loop = loop
    this.#executionID = executionID
    this.#graph = getLoopGraph(loop.nodes)
    this.#nodePromises = new Map()
    this.#abortController = new AbortController()
  }

  async run(onProgress: ProgressCallback, onGetExecution: GetExecutionCallback): Promise<void> {
    const outputNodes = getOutputNodes(this.#loop)
    if (outputNodes.length === 0) throw new Error('No output node')
    await Promise.all(outputNodes.map(node => this.#runNodeUnlessRunning(node, onProgress, onGetExecution)))
  }

  stop(cancelExecution: (executionID: string) => void): void {
    this.#abortController.abort()
    cancelExecution(this.#executionID)
  }

  #isCancelled(): boolean {
    return this.#abortController.signal.aborted
  }

  async #runNodeUnlessRunning(
    node: Node,
    onProgress: ProgressCallback,
    onGetExecution: GetExecutionCallback,
  ): Promise<NodeValue> {
    const existing = this.#nodePromises.get(node.id)
    if (existing) return existing

    const promise = this.#runNode(node, onProgress, onGetExecution)
    this.#nodePromises.set(node.id, promise)

    return promise
  }

  async #runNode(node: Node, onProgress: ProgressCallback, onGetExecution: GetExecutionCallback): Promise<NodeValue> {
    if (this.#isCancelled()) return null

    const executionResult = await onGetExecution(this.#loop.id, this.#loop.version || draftVersion, this.#executionID)
    if (!executionResult.success) throw new Error('Unable to load execution')
    const execution = executionResult.data
    const existingValue = execution.nodes[node.id]?.value
    if (existingValue) return existingValue

    const predecessorIDs = new Set(this.#graph.edges.filter(e => e.to === node.id).map(e => e.from))
    const predecessors = [...predecessorIDs].map(id => this.#loop.nodes.find(n => n.id === id)).filter(n => !!n)

    // Recurse
    const predecessorValues = await Promise.all(
      predecessors.map(async p => [p.id, await this.#runNodeUnlessRunning(p, onProgress, onGetExecution)]),
    )
    if (predecessorValues.some(([_, value]) => value === null)) {
      return null
    }
    if (this.#isCancelled()) return null

    const predecessorValueMap = Object.fromEntries(predecessorValues)
    try {
      const filledNode = replaceVariablesInNode(node, predecessorValueMap)
      const runner = new NodeRunner(filledNode, this.#graphQLClient, this.#chatClient)

      onProgress({type: 'SET_RUNNING', nodeID: node.id})
      const onPartialResult = (result: string) => {
        if (!this.#isCancelled()) {
          onProgress({
            type: 'UPDATE_NODE_VALUE_PARTIAL',
            nodeID: node.id,
            value: result,
          })
        }
      }

      const out = await runner.run(this.#abortController.signal, onPartialResult, execution)

      // Don't update state if aborted
      if (!this.#isCancelled()) {
        onProgress({
          type: 'UPDATE_NODE_VALUE',
          nodeID: node.id,
          value: out,
        })
      }

      return out
    } catch (e) {
      if (!this.#isCancelled()) {
        onProgress({
          type: 'UPDATE_NODE_ERROR',
          nodeID: node.id,
          error: getErrorMessage(e),
        })
      }

      return null
    }
  }
}

function getErrorMessage(e: unknown) {
  if (e instanceof Error) return e.message
  if (typeof e === 'string') return e
  if (typeof e === 'object') return JSON.stringify(e)
  return ''
}
