import {useLoopsStateLens} from '../contexts/LoopsStateProvider'
import {draftVersion, latestVersion} from '../utils/versions'
import {useLoopLens} from './use-loop-lens'
export type ReadonlyReason = 'shared' | 'previousVersion'

/**
 * Hook to determine if the current loop should be readonly.
 * A loop is readonly if it's being viewed via a shared link.
 *
 * @returns readonly state object with explicit loading flag
 */
export function useIsReadonly(): {isReadonly: boolean; isLoading: boolean; reason?: ReadonlyReason} {
  const version = useLoopsStateLens(state => state.version)
  const owned = useLoopLens(l => l?.owned)

  const isPreviousVersion = version !== draftVersion && version !== latestVersion

  if (owned === undefined) {
    return {isReadonly: false, isLoading: true}
  }

  if (owned === false) {
    return {isReadonly: true, isLoading: false, reason: 'shared'}
  }

  if (isPreviousVersion) {
    return {isReadonly: true, isLoading: false, reason: 'previousVersion'}
  }

  return {isReadonly: false, isLoading: false}
}
