import {RowsIcon, ThreeBarsIcon} from '@primer/octicons-react'
import {SegmentedControl} from '@primer/react'

export interface ListModeToggleProps {
  value: 'list' | 'output'
  onChange: (value: 'list' | 'output') => void
}

export function ListModeToggle({value, onChange}: ListModeToggleProps) {
  const handleChange = (index: number) => {
    onChange(index === 0 ? 'list' : 'output')
  }

  return (
    <SegmentedControl aria-label="Loops overview view mode" onChange={handleChange}>
      <SegmentedControl.IconButton aria-label="List view" selected={value === 'list'} icon={ThreeBarsIcon} />
      <SegmentedControl.IconButton aria-label="Output view" selected={value === 'output'} icon={RowsIcon} />
    </SegmentedControl>
  )
}

try{ ListModeToggle.displayName ||= 'ListModeToggle' } catch {}