import {ConsecutiveCAPI401sProvider} from '@github-ui/agent-sessions/contexts/ConsecutiveCAPI401sContext'
import {noop} from '@github-ui/noop'
import {TriangleDownIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Button, ButtonGroup, IconButton, Label} from '@primer/react'
import {useMemo, useState} from 'react'

import type {PlanningTask} from '../content-preview-types'
import {MarkdownPreview} from '../MarkdownPreview'
import styles from './PlanningTaskPreview.module.css'
import {usePlanningTaskPullRequest, useStartAgentSession} from './utils/agent-session'
import {useConvertToDraftIssue} from './utils/use-convert-to-draft-issue'

interface PlanningTaskPreviewProps {
  task: PlanningTask
}

export function PlanningTaskPreview({task}: PlanningTaskPreviewProps) {
  const markdownContent = useMemo(() => {
    return task.name ? `# ${task.name}\n\n${task.description}` : task.description
  }, [task.name, task.description])

  return (
    <div className={styles.container}>
      <div className={styles.toolbar}>
        <PlanningTaskToolbar task={task} />
      </div>

      <MarkdownPreview
        content={{
          value: markdownContent,
          name: `${task.tag}.md`,
        }}
        hideHeadingAnchors
        fallbackToRaw
      />
    </div>
  )
}

interface PlanningTaskToolbarProps {
  task: PlanningTask
}

function PlanningTaskToolbar({task}: PlanningTaskToolbarProps) {
  return (
    // Used by `useCAPIQuery` within `usePlanningTaskPullRequest` for tracking authentication failures in CAPI requests.
    <ConsecutiveCAPI401sProvider>
      <PlanningTaskToolbarImpl task={task} />
    </ConsecutiveCAPI401sProvider>
  )
}

function PlanningTaskToolbarImpl({task}: {task: PlanningTask}) {
  const [isOpen, setIsOpen] = useState(false)
  const {start: startAgentSession, isStarting: isStartingAgentSession} = useStartAgentSession(task)
  const {pullRequest, isLoading: isPullRequestDataLoading} = usePlanningTaskPullRequest(task)

  const {convertToDraftIssue} = useConvertToDraftIssue(task)

  const isLoading = isPullRequestDataLoading || isStartingAgentSession
  const repoNwo = pullRequest?.repository_nwo ?? task.repository // Prefer pull request info

  return (
    <>
      <div className={styles.toolbarLeft}>
        {repoNwo && (
          <Label variant="accent" size="large" className={styles.toolbarRepo}>
            {repoNwo}
          </Label>
        )}
      </div>
      <div className={styles.toolbarActions}>
        {pullRequest != null ? (
          <>
            <Button
              as="a"
              href={`/${pullRequest.repository_nwo}/pull/${pullRequest.number}/agent-sessions`}
              variant="primary"
              size="small"
            >
              View sessions
            </Button>
            <Button
              as="a"
              href={`/${pullRequest.repository_nwo}/pull/${pullRequest.number}`}
              variant="primary"
              size="small"
            >
              View pull request
            </Button>
          </>
        ) : (
          <ButtonGroup className={styles.taskOptionsButtonGroup}>
            <Button
              variant="primary"
              onClick={isLoading ? noop : startAgentSession}
              className={styles.taskOptionsButton}
              loading={isLoading}
              loadingAnnouncement="Starting task…"
              inactive={isLoading}
            >
              Start task with Copilot
            </Button>
            <div className={styles.taskOptionsDivider} />
            <ActionMenu open={isOpen} onOpenChange={open => setIsOpen(open)}>
              <ActionMenu.Anchor aria-label={'Task options'}>
                <IconButton
                  variant="primary"
                  icon={TriangleDownIcon}
                  aria-label="Task options…"
                  className={styles.taskOptionsMenuButton}
                />
              </ActionMenu.Anchor>
              <ActionMenu.Overlay>
                <ActionList>
                  <ActionList.Item onSelect={convertToDraftIssue}>Draft issue</ActionList.Item>
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          </ButtonGroup>
        )}
      </div>
    </>
  )
}

try{ PlanningTaskPreview.displayName ||= 'PlanningTaskPreview' } catch {}
try{ PlanningTaskToolbar.displayName ||= 'PlanningTaskToolbar' } catch {}
try{ PlanningTaskToolbarImpl.displayName ||= 'PlanningTaskToolbarImpl' } catch {}