/**
 * Compares two date strings.
 * @param date1 The first date string to compare.
 * @param date2 The second date string to compare.
 * @returns A negative number if date1 is earlier than date2, a positive number if date1 is later than date2, and 0 if they are equal.
 */
export function compareDateStrings(date1: string, date2: string): number {
  return new Date(date1).getTime() - new Date(date2).getTime()
}

/**
 * Validates if a string is a valid date macro.
 * Macro format: @today[+/-]{number}{unit}
 * Example: @today, @today+1d, @today-2w, @today+3m, @today-1y
 */
export function isValidMacro(input: string): boolean {
  const macroRegex = /^@today([+-]\d+[dwmy])?$/
  return macroRegex.test(input)
}

/**
 * Validates if a string is a valid date.
 */
export function isValidDate(dateString: string): boolean {
  // Reject strings that start with @ as they should be handled by macro validation
  if (dateString.startsWith('@')) {
    return false
  }

  const date = new Date(dateString)
  if (isNaN(date.getTime())) {
    return false
  }

  // Check if the date string is in a strict format and matches what was parsed
  // This prevents JavaScript from auto-correcting invalid dates like '2025-02-30'
  if (dateString.match(/^\d{4}-\d{2}-\d{2}$/)) {
    // For YYYY-MM-DD format, ensure the parsed date matches the input
    const datePart = formatDateAsYYYYMMDD(date)
    return datePart === dateString
  }

  return true
}

/**
 * Validates if a string is either a valid date or a valid macro.
 */
export function isValidDateOrMacro(input: string): boolean {
  return isValidMacro(input) || isValidDate(input)
}

/**
 * Result of parsing a macro string.
 */
export interface ParseMacroResult {
  date: Date | null
  error?: string
}

/**
 * Parses a macro string and returns the corresponding Date object.
 * @param macro The macro string to parse (e.g., "@today+1d", "@today-2w")
 * @returns Object containing the calculated Date object or error message
 */
export function parseMacro(macro: string): ParseMacroResult {
  if (!isValidMacro(macro)) {
    return {date: null, error: `Invalid macro format: ${macro}`}
  }

  const today = new Date()

  // If it's just "@today", return today's date
  if (macro === '@today') {
    return {date: today}
  }

  // Parse the offset part (+/-{number}{unit})
  const offsetMatch = macro.match(/^@today([+-])(\d+)([dwmy])$/)
  if (!offsetMatch) {
    return {date: null, error: `Invalid macro format: ${macro}`}
  }

  const [, operator, numberStr, unit] = offsetMatch
  if (!operator || !numberStr || !unit) {
    return {date: null, error: `Invalid macro format: ${macro}`}
  }

  const number = parseInt(numberStr, 10)
  const isPositive = operator === '+'

  // Calculate the offset
  const result = new Date(today)

  switch (unit) {
    case 'd': // days
      result.setDate(result.getDate() + (isPositive ? number : -number))
      break
    case 'w': // weeks
      result.setDate(result.getDate() + (isPositive ? number * 7 : -number * 7))
      break
    case 'm': // months
      result.setMonth(result.getMonth() + (isPositive ? number : -number))
      break
    case 'y': // years
      result.setFullYear(result.getFullYear() + (isPositive ? number : -number))
      break
    default:
      return {date: null, error: `Invalid unit: ${unit}`}
  }

  return {date: result}
}

/**
 * Converts a date string or macro to a Date object.
 * @param input A date string or macro
 * @returns Date object if valid, null if invalid
 */
export function parseStringToDate(input: string): Date | null {
  // If it starts with @ but isn't a valid macro, reject it
  if (input.startsWith('@') && !isValidMacro(input)) {
    return null
  }

  if (isValidMacro(input)) {
    const result = parseMacro(input)
    return result.date
  }

  if (isValidDate(input)) {
    return new Date(input)
  }

  return null
}

/**
 * Formats a Date object as a YYYY-MM-DD string.
 * @param date The Date object to format
 * @returns A string in YYYY-MM-DD format
 */
export function formatDateAsYYYYMMDD(date: Date): string {
  const isoString = date.toISOString()
  const datePart = isoString.split('T')[0]
  return datePart ?? isoString.substring(0, 10)
}
