import {DiffFileHeader} from '@github-ui/diff-file-header'
import type {DiffEntry} from '@github-ui/diff-lines/conversation-types'
import {StaticUnifiedDiffPreview} from '@github-ui/diff-lines/static-unified-diff-preview'
import {FileIcon} from '@primer/octicons-react'
import {useState} from 'react'

import type {TaskDiff} from './content-preview-types'
import styles from './TaskDiffPreview.module.css'

export interface TaskDiffPreviewProps {
  taskDiff: TaskDiff
}

interface DiffFileSectionProps {
  diffEntry: DiffEntry
  tabSize: number
}

function DiffFileSection({diffEntry, tabSize}: DiffFileSectionProps) {
  const [isCollapsed, setIsCollapsed] = useState(false)

  const linesAdded = diffEntry.diffLines.filter(line => line.type === 'ADDITION').length
  const linesDeleted = diffEntry.diffLines.filter(line => line.type === 'DELETION').length
  const linesChanged = diffEntry.diffLines.length

  return (
    <div className={styles.diffFileSection}>
      <DiffFileHeader
        className={styles.taskDiffHeader}
        isCollapsed={isCollapsed}
        linesAdded={linesAdded}
        linesChanged={linesChanged}
        linesDeleted={linesDeleted}
        newPath={diffEntry.path}
        oldPath={diffEntry.path}
        onToggleFileCollapsed={() => setIsCollapsed(!isCollapsed)}
        patchStatus="MODIFIED"
        path={diffEntry.path}
      />
      {!isCollapsed && (
        <StaticUnifiedDiffPreview
          diffLines={diffEntry.diffLines}
          tabSize={tabSize}
          className={styles.diffFiles}
          diffTableClassName={styles.diffTable}
        />
      )}
    </div>
  )
}

export function TaskDiffPreview({taskDiff}: TaskDiffPreviewProps) {
  const {diffEntries, tabSize} = taskDiff
  const hasDiffEntries = diffEntries && diffEntries.length > 0

  return (
    <div className={styles.container}>
      {!hasDiffEntries ? (
        <div className={styles.emptyState}>
          <div className={styles.emptyStateContent}>
            <FileIcon size={48} />
            <h3 className={styles.emptyStateTitle}>No code changes</h3>
            <p className={styles.emptyStateText}>There are no file changes to display.</p>
          </div>
        </div>
      ) : (
        <div className={styles.diffFiles}>
          {diffEntries.map(diffEntry => (
            <DiffFileSection key={diffEntry.path} diffEntry={diffEntry} tabSize={tabSize} />
          ))}
        </div>
      )}
    </div>
  )
}

try{ DiffFileSection.displayName ||= 'DiffFileSection' } catch {}
try{ TaskDiffPreview.displayName ||= 'TaskDiffPreview' } catch {}