import {fetchSearchAssignees} from '@github-ui/item-picker-assignee-relay'
import {getActorCapabilities} from '@github-ui/item-picker-assignee-relay/utils/assignee-picker'
import {useQuery} from '@github-ui/react-query'
import {useRelayEnvironment} from 'react-relay'

export function useAssigneesQuery({
  owner,
  repo,
  assignees,
}: {
  owner: string | undefined
  repo: string | undefined
  assignees: string[] | undefined
}) {
  const environment = useRelayEnvironment()
  const capabilities = getActorCapabilities({includeAuthorableBots: false, includeAssignableBots: true})

  return useQuery({
    queryKey: ['copilot-immersive-assignees', JSON.stringify(environment), capabilities, owner, repo, assignees],
    queryFn: async () => {
      if (!owner || !repo || !assignees) return []

      const data = await fetchSearchAssignees(environment, {
        owner,
        repo,
        assignees,
        capabilities,
      })

      return data
    },
  })
}
