import {useQuery} from '@github-ui/react-query'
import type {Loop} from '../../types/app'
import type {Execution} from '../../types/execution'
import {useLoopsService} from '../../contexts/LoopsServiceProvider'
import {latestVersion} from '../../utils/versions'
import {isExecutionRunning} from '../../utils/execution-helpers'

export function loopExecutionQueryKey(loopId: string, loopVersion: string) {
  return ['loop-execution', loopId, loopVersion] as const
}

export function useLoopExecution<T = Execution | null>(loop: Loop, selector?: (execution: Execution | null) => T) {
  const service = useLoopsService()
  const loopId = loop.id
  const loopVersion = loop.version ?? ''

  return useQuery({
    queryKey: loopExecutionQueryKey(loopId, loopVersion),
    queryFn: async () => {
      const result = await service.getExecution(loopId, loopVersion, latestVersion)
      if (!result.success) return null
      const execution = result.data
      const isRunningMatch = service.isExecutionRunning(execution.id) === isExecutionRunning(execution)
      if (!isRunningMatch) return null
      return execution
    },
    enabled: true,
    ...(selector && {select: selector}),
    staleTime: 5 * 60 * 1000,
  })
}
