import styles from './RunningDisplay.module.css'
import {CopilotAnimation} from '@github-ui/copilot-animation'

interface RunningDisplayProps {
  isRunning: boolean
  messages?: {
    running: string
    waiting: string
  }
}

export function RunningDisplay({isRunning, messages}: RunningDisplayProps) {
  const defaultMessages = {
    running: 'Running...',
    waiting: 'Waiting...',
  }

  const displayMessages = messages || defaultMessages
  const message = isRunning ? displayMessages.running : displayMessages.waiting

  return (
    <div className={styles.container}>
      <CopilotAnimation animationType={isRunning ? 'thinking' : 'static'} loopAnimation />
      <div className={styles.text}>{message}</div>
    </div>
  )
}

try{ RunningDisplay.displayName ||= 'RunningDisplay' } catch {}