import type {
  Node,
  Loop,
  LoopGraph,
  LoopInputValue,
  TextNodeMetadata,
  CanvasGraph,
  VirtualNode,
  GraphNode,
} from '../types/app'
import {isPipelineNode, isTextNode} from './node-assertions'
import {logError, logWarning} from './console'
import {getNodeReferenceRegex} from './utils'
import {inputTypeInfo} from '../types/input-types'
import {nodeHandlerRegistry} from '../service/node-handler-registry'

export type IsRunningCallback = (nodeId: string, isRunning: boolean) => void
export type ResultsCallback = (results: Map<string, string>) => void

export function getLoopGraph(nodes: Node[]): LoopGraph {
  const graph: LoopGraph = {
    nodes: new Map<string, Node>(),
    edges: [],
    layers: [],
  }
  if (!nodes) return graph

  // Add all nodes to the graph
  for (const node of nodes) {
    if (!node?.id) continue
    const id = getInputId(node.id)
    graph.nodes.set(id, node)
  }

  // Create edges from inputs
  for (const node of nodes) {
    for (const input of getInputs(node)) {
      const id = getInputId(input)
      if (!node?.id || !id) continue
      graph.edges.push({
        from: id,
        to: node.id,
      })
    }
  }

  const layers = getLayers(graph)
  graph.layers = layers

  return graph
}

export function getInputs(node: Node): Set<string> {
  const nodeReferenceRegex = getNodeReferenceRegex()
  const variableMatches = node.content.match(nodeReferenceRegex) || []
  return new Set(variableMatches.map(match => match.replace(/[{}]/g, '')))
}

export function getInputIds(node: Node): Set<string> {
  return new Set([...getInputs(node)].map(getInputId))
}

export function getInputId(input: string): string {
  // matches anything before the first | or . in the input
  return input.match(/^[^|.]+/)?.[0] ?? input
}

function getLayers(graph: LoopGraph): Node[][] {
  const nodeLayers: Record<string, number> = {}
  const maxRecursionDepth = 100
  const nodeStack = new Set<string>()

  const computeNodeLayer = (nodeId: string, depth = 0): number => {
    try {
      if (nodeStack.has(nodeId)) {
        throw new Error(`Potential cycle detected at node ${nodeId}`)
      }
      nodeStack.add(nodeId)

      // Guard against infinite recursion
      if (depth > maxRecursionDepth) {
        logWarning(`Maximum recursion depth reached for node ${nodeId}`)
        return 0
      }

      // Return cached result if available
      if (nodeLayers[nodeId] !== undefined) {
        return nodeLayers[nodeId]
      }

      const node = graph.nodes.get(nodeId)
      if (!node) {
        nodeLayers[nodeId] = 0
        return 0
      }

      const nodeInputs = getInputs(node)
      if (!nodeInputs || nodeInputs.size === 0) {
        const outputs = graph.edges.filter(e => e.from === nodeId).map(e => e.to)
        if (outputs.length === 0) {
          nodeLayers[nodeId] = -1
        } else {
          nodeLayers[nodeId] = 1
        }
      } else {
        // Compute the layer as one more than the max layer among inputs
        const inputLayers = [...nodeInputs].map(input => {
          const inputId = getInputId(input)
          return computeNodeLayer(inputId, depth + 1)
        })
        nodeLayers[nodeId] = Math.max(...inputLayers) + 1
      }

      return nodeLayers[nodeId]
    } finally {
      nodeStack.delete(nodeId) // Always clean up the stack
    }
  }

  // Compute layers for all nodes
  for (const [nodeId] of graph.nodes) {
    if (!nodeLayers[nodeId]) {
      try {
        computeNodeLayer(nodeId)
      } catch (e) {
        logError(`Error computing layer for node ${nodeId}:`, e)
        nodeLayers[nodeId] = 0
      }
    }
  }

  // Reassign MAX to the last layer
  const maxLayer = Math.max(...Object.values(nodeLayers)) + 1
  for (const nodeId of Object.keys(nodeLayers)) {
    if (nodeLayers[nodeId] === -1) {
      nodeLayers[nodeId] = maxLayer
    }
  }

  // Build the layers array
  const layers: Node[][] = []
  for (const [nodeId, layer] of Object.entries(nodeLayers)) {
    const node = graph.nodes.get(nodeId)
    if (node) {
      if (!layers[layer]) {
        layers[layer] = []
      }
      layers[layer].push(node)
    }
  }

  return layers.filter(Boolean)
}

function getNodeInputType(node: Node): TextNodeMetadata | undefined {
  if (!isTextNode(node)) return undefined

  return inputTypeInfo[node.metadata.inputType] ? node.metadata : {inputType: 'text'}
}

export const sanitizeNode = (node: Node, pipelines: Loop[]): Node | null => {
  if (!node || typeof node !== 'object') {
    return null
  }

  if (!node.title && !node.description && !node.content) {
    return null
  }

  const sanitizedNode = {
    ...node,
    title: node.title || '',
    description: node.description || '',
    type: nodeHandlerRegistry.getMetadata(node.type) ? node.type : 'text',
    content: node.content || '',
    id: (node.id || '').trim(),
  } as Node

  if (sanitizedNode.type === 'text') {
    sanitizedNode.metadata = getNodeInputType(node) || {inputType: 'text'}
  }

  if (typeof sanitizedNode.content !== 'string') {
    sanitizedNode.content = ''
  }
  if (isPipelineNode(sanitizedNode)) {
    const selectedPipe = pipelines.find(pipe => pipe.id === sanitizedNode.loopId)
    if (selectedPipe) {
      const inputValueNodeIdMap =
        sanitizedNode.loopInputValues?.reduce((result: {[key: string]: LoopInputValue}, input: LoopInputValue) => {
          result[input.inputId] = input
          return result
        }, {}) || {}

      sanitizedNode.loopInputValues = selectedPipe.nodes
        ?.filter(n => isTextNode(n))
        .map(textNode => {
          const input = inputValueNodeIdMap[textNode.id]
          if (!input) throw new Error(`Input not found for node ${textNode.id}`)

          return {
            inputId: textNode.id,
            nodeId: input.nodeId,
            doMapInput: !!input.doMapInput,
          }
        })
    }
  }

  return sanitizedNode
}

export const sanitizeLoop = (pipeline: Loop, pipelines: Loop[]): Loop => {
  const migratedLoop = tempMigrateGeneratedLoop(pipeline)
  const sanitizedPipeline = {
    ...migratedLoop,
    nodes: (migratedLoop.nodes || [])
      .map((node: Node) => sanitizeNode(node, pipelines))
      .filter((node): node is Node => node !== null),
  }
  return sanitizedPipeline
}

/**
 * This function migrates existing loops based on breaking changes
 * to the Loop typing. This can be removed once it has been in
 * production for a while.
 * TODO: remove
 */
function tempMigrateGeneratedLoop(loop: Loop): Loop {
  return {
    ...loop,
    nodes: loop.nodes.map(tempMigrateGeneratedNode),
  }
}

function tempMigrateGeneratedNode(node: Node): Node {
  if (node.type === 'prompt' && 'model' in node && typeof node.model === 'string') {
    return {
      ...node,
      metadata: {model: node.model},
    }
  } else if (node.type === 'text' && 'inputType' in node) {
    return {
      ...node,
      metadata: tempMigrateGeneratedInputType(node.inputType as TextNodeMetadata),
    }
  }
  return node
}

function tempMigrateGeneratedInputType(meta: TextNodeMetadata): TextNodeMetadata {
  if ('type' in meta && typeof meta.type === 'string') {
    const inputType = meta.type === 'file' ? 'text' : (meta.type as TextNodeMetadata['inputType'])
    return {
      ...meta,
      inputType,
    } as TextNodeMetadata
  }
  return meta
}

export function getOutputNodes(pipeline: Loop): Node[] {
  const graph = getLoopGraph(pipeline.nodes)
  return pipeline.nodes.filter(n => isOutputNode(n, graph))
}

/**
 * Get pipeline graph with a single virtual output node for canvas display.
 * All output nodes (nodes with predecessors but no successors) will connect to one shared virtual output node.
 */
export function getCanvasLoopGraph(graph: LoopGraph): CanvasGraph {
  const canvasGraph: CanvasGraph = {
    nodes: new Map<string, GraphNode>(),
    edges: [...graph.edges],
    layers: [...graph.layers],
  }

  for (const [id, node] of graph.nodes) {
    canvasGraph.nodes.set(id, node)
  }

  const outputNodes = [...graph.nodes].filter(([, n]) => isOutputNode(n, graph))
  if (outputNodes.length > 0) {
    const virtualNodeId = 'virtual-output'
    const virtualNode: VirtualNode = {
      type: 'output',
      id: virtualNodeId,
    }

    canvasGraph.nodes.set(virtualNodeId, virtualNode)

    // Add edges from all output nodes to the single virtual node
    for (const [, outputNode] of outputNodes) {
      canvasGraph.edges.push({
        from: outputNode.id,
        to: virtualNodeId,
      })
    }
  }

  return canvasGraph
}

/**
 * Check if a node is a virtual output node
 */
export function isVirtualOutputNode(nodeId: string): boolean {
  return nodeId === 'virtual-output'
}

/**
 * A node is an output node if it has predecessors but no successors
 */
function isOutputNode(node: Node, graph: LoopGraph): boolean {
  return !graph.edges.some(e => e.from === node.id) && graph.edges.some(e => e.to === node.id)
}
