/**
 * Handler for prompt nodes - uses AI chat completion
 */
export class PromptNodeHandler implements NodeHandler<PromptNode> {
  readonly type = 'prompt' as const
  readonly metadata = {
    contentFields: ['content'] as Array<keyof PromptNode>,
    icon: () => CopilotIcon,
    description: () => 'Use AI to process a node',
    label: () => 'Prompt',
    color: 'purple' as const,
    type: 'prompt' as const,
    outputLabel: 'Markdown',
    isExecutable: true,
    enabled: () => true,
  }

  protected logTokenUsage(tokenType: string, value: number, model: string): void {
    sendEvent('loops.prompt_node.token_usage', {
      model,
      token_type: tokenType,
      token_value: value,
    })
  }

  async execute(node: PromptNode, context: NodeExecutionContext): Promise<NodeValue> {
    const messages = await createNodePromptChat(node)

    let result = ''
    let totalUsage: TokenUsage | undefined

    for await (const chunk of context.chatClient.getChatCompletion(messages, node.metadata?.model, context.signal)) {
      result += chunk.content

      // Capture usage data from the final chunk
      if (chunk.usage) {
        totalUsage = chunk.usage
      }

      context.onPartialResult?.(result)
    }

    // Log token usage to datadog for telemetry
    if (totalUsage) {
      this.logTokenUsage('TOTAL_TOKEN', totalUsage.total_tokens, totalUsage.model)
      this.logTokenUsage('PROMPT_TOKEN', totalUsage.prompt_tokens, totalUsage.model)
      this.logTokenUsage('COMPLETION_TOKEN', totalUsage.completion_tokens, totalUsage.model)
    }

    return result
  }

  validate(_node: PromptNode): LoopValidationError[] {
    return []
  }
}

/**
 * Handler for GitHub GraphQL nodes - fetches data from GitHub API
 */
export class GitHubGraphQLNodeHandler implements NodeHandler<GitHubGraphQLNode> {
  readonly type = 'github-graphql' as const
  readonly metadata = {
    type: 'github-graphql' as const,
    contentFields: ['content'] as Array<keyof GitHubGraphQLNode>,
    icon: () => MarkGithubIcon,
    description: () => 'Retrieve data from GitHub',
    label: () => 'GitHub GraphQL',
    color: 'gray' as const,
    enabled: isGitHubGraphQLNodesEnabled,
    outputLabel: 'JSON',
    isExecutable: true,
  }

  async execute(node: GitHubGraphQLNode, context: NodeExecutionContext): Promise<NodeValue> {
    const graphQLResult = await context.graphQLClient.getGraphQLResponse(node.content, context.signal)

    if (!graphQLResult) return null

    const result = graphQLResult as {data?: unknown; resources?: unknown}
    return {
      data: result.data ?? null,
      resources: result.resources ?? null,
    }
  }

  validate(_node: GitHubGraphQLNode): LoopValidationError[] {
    return []
  }
}

