/**
 * Handler for text nodes - input nodes with various input types
 */
export class TextNodeHandler implements NodeHandler<TextNode> {
  readonly type = 'text' as const
  readonly metadata = {
    type: 'text' as const,
    contentFields: ['content'] as Array<keyof TextNode>,
    icon: (node?: TextNode) => {
      if (node && isTextNode(node)) {
        if (node.metadata.inputType === 'boolean') {
          if (node.content === 'true') {
            return BooleanOnIcon
          } else {
            return BooleanOffIcon
          }
        }

        return getInputNodeTypeField(node, 'icon')
      }
      return TypographyIcon
    },
    description: (node?: TextNode) => {
      if (node && isTextNode(node)) return getInputNodeTypeField(node, 'description')
      return 'Input for nodes'
    },
    label: (node?: TextNode) => {
      if (node && isTextNode(node)) return getInputNodeTypeField(node, 'name')
      return 'Input'
    },
    color: 'blue' as const,
    enabled: () => true,
  }

  async execute(node: TextNode, context: NodeExecutionContext): Promise<NodeValue> {
    // Get the value to process - either custom input or node content
    const customValue = context.execution?.inputValues?.[node.id]
    const valueToProcess = customValue !== undefined ? customValue : getDefaultNodeContent(node)

    // Process date macros if this is a date input type
    if (node.metadata.inputType === 'date' && typeof valueToProcess === 'string' && isValidMacro(valueToProcess)) {
      const parsedDate = parseStringToDate(valueToProcess)
      if (parsedDate) {
        return formatDateAsYYYYMMDD(parsedDate)
      }
    }

    return valueToProcess
  }

  validate(node: TextNode): LoopValidationError[] {
    const errors: LoopValidationError[] = []
    const input = node.metadata

    if (typeof input !== 'object' || !input) {
      errors.push({
        error: `metadata is required for text nodes`,
        errorType: loopErrorType.MissingProperty,
        involvedNodes: [node.id],
      })
      return errors
    }

    switch (input.inputType) {
      case 'boolean':
        if (!['true', 'false'].includes(node.content)) {
          errors.push({
            error: `A boolean input must have a value of either "true" or "false"`,
            errorType: loopErrorType.InvalidBooleanValue,
            involvedNodes: [node.id],
          })
        }
        break
      case 'range':
        if (typeof input.min !== 'number') {
          errors.push({
            error: `A range input must have a min`,
            errorType: loopErrorType.InvalidRangeValue,
            involvedNodes: [node.id],
          })
        }
        if (typeof input.max !== 'number') {
          errors.push({
            error: `A range input must have a max`,
            errorType: loopErrorType.InvalidRangeValue,
            involvedNodes: [node.id],
          })
        }
        break
      case 'select':
        if (!Array.isArray(input.options) || input.options.length === 0) {
          errors.push({
            error: `A select input must have options`,
            errorType: loopErrorType.InvalidSelectValue,
            involvedNodes: [node.id],
          })
        } else if (!input.options.includes(node.content)) {
          errors.push({
            error: `A select node must have content equal to one of its options`,
            errorType: loopErrorType.InvalidSelectValue,
            involvedNodes: [node.id],
          })
        }
        break
      case 'date':
        if (!node.content) {
          errors.push({
            error: `Date input needs a value`,
            errorType: loopErrorType.EmptyInputValue,
            involvedNodes: [node.id],
          })
        } else if (!isValidDateOrMacro(node.content)) {
          errors.push({
            error: `Date input must be a valid date (YYYY-MM-DD) or date macro (e.g., @today, @today+1d, @today-2w)`,
            errorType: loopErrorType.InvalidDateValue,
            involvedNodes: [node.id],
          })
        }
        break
      case 'text':
        if (!node.content) {
          errors.push({
            error: `Input needs a value`,
            errorType: loopErrorType.EmptyInputValue,
            involvedNodes: [node.id],
          })
        }
        break
    }
    return errors
  }
}

