// eslint-disable-next-line @github-ui/github-monorepo/filename-convention
import type {CopilotMarkdownExtension, ReactComponentsExtension} from '@github-ui/copilot-markdown/extension'
import {dataAttrToPropName, parseJsonAttribute} from '@github-ui/copilot-markdown/utils'
import {visit} from 'unist-util-visit'

import {stripQuotes, typeRawRegex} from '../../utils/code-block-utils'
import {
  PlanningTasklistBlock,
  planningTasklistBlockAttribute,
  type PlanningTasklistBlockProps,
} from './PlanningTasklistBlock'

const planningTasklistBlockProperty = dataAttrToPropName(planningTasklistBlockAttribute)

const reactComponents: ReactComponentsExtension = {
  div: (props, fallthrough) => {
    const planningTasklistProps = parseJsonAttribute<PlanningTasklistBlockProps>(props, planningTasklistBlockAttribute)
    if (!planningTasklistProps) return fallthrough

    return <PlanningTasklistBlock {...planningTasklistProps} />
  },
}

export function planningTasklistExtension(): CopilotMarkdownExtension {
  return {
    transformMarkdown: tree =>
      visit(tree, 'code', node => {
        if (node.lang !== 'yaml') return

        const type = stripQuotes(typeRawRegex.exec(node.meta ?? '')?.groups?.type ?? '')
        if (type !== 'planning-tasklist') return

        node.data = {
          hName: 'div',
          hProperties: {
            [planningTasklistBlockProperty]: JSON.stringify({
              yaml: node.value,
              isStreaming: node.isStreaming ?? false,
            } satisfies PlanningTasklistBlockProps),
          },
          hChildren: [],
        }
      }),
    transformHtml: tree =>
      // Code nodes render as two nested elements (pre > code) by default, and setting the hName only overrides the
      // inner element. So we have to transform the html by removing the outer element
      // TODO: Reduce duplication with file blocks logic
      visit(tree, 'element', (node, i, parent) => {
        const child = node.children?.[0]
        if (
          parent &&
          i != null &&
          node.tagName === 'pre' &&
          node.children?.length === 1 &&
          child?.type === 'element' &&
          planningTasklistBlockProperty in child.properties
        )
          parent.children.splice(i, 1, child)
      }),
    reactComponents,
  }
}
