import {useQuery} from '@github-ui/react-query'
import {useLoopsService} from '../../contexts/LoopsServiceProvider'
import type {Execution} from '../../types/execution'
import {isExecutionRunning} from '../../utils/execution-helpers'
import {draftVersion, latestVersion} from '../../utils/versions'
import {useLoopsStateLens} from '../../contexts/LoopsStateProvider'
import {useLoop} from './use-loop'

export const EXECUTION_QUERY_KEY = 'execution'

export function useExecutionVersion() {
  const {data: loopVersion} = useLoop(loop => loop?.version, 'latest')
  const versionInState = useLoopsStateLens(s => s.version)

  if (versionInState === latestVersion || versionInState === draftVersion) {
    // executions API doesn't accept relative versions like 'draft' or 'latest'
    return loopVersion
  }

  return versionInState
}

export function executionQueryKey(loopID: string, loopVersion: string) {
  return [EXECUTION_QUERY_KEY, loopID, loopVersion] as const
}

export function useExecutionQueryKey() {
  const {data: loopID} = useLoop(loop => loop?.id)
  const version = useExecutionVersion()
  return executionQueryKey(loopID ?? '', version ?? '')
}

export function useExecution<T = Execution | null>(selector?: (execution: Execution | null | undefined) => T) {
  const {data: loopID} = useLoop(loop => loop?.id)
  const version = useExecutionVersion()
  const service = useLoopsService()

  return useQuery({
    queryKey: executionQueryKey(loopID ?? '', version ?? ''),
    queryFn: async () => {
      if (!loopID || !version) return null

      const result = await service.getExecution(loopID, version, latestVersion)
      if (!result.success) {
        const error = new Error('Error fetching execution.')
        error.cause = result.httpStatus
        throw error
      }

      const execution = result.data

      // If the running state doesn't match, the previous execution was interrupted. Just discard it.
      const isRunningMatch = service.isExecutionRunning(execution.id) === isExecutionRunning(execution)
      if (!isRunningMatch) {
        return null
      }

      return execution
    },
    enabled: !!loopID && !!version,
    ...(selector && {select: selector}),
    staleTime: 5 * 60 * 1000, // 5 minutes
    retry: (failureCount, error) => {
      if (error?.cause === 404) {
        return false
      }

      return failureCount < 3
    },
  })
}
