import {lazy} from 'react'

// Lazy load the Loop component
export const LazyLoop = lazy(async () => {
  const module = await import('./Loop')
  return {
    default: module.Loop,
  }
})

// Preload function to warm the component
export function preloadLoopComponent() {
  // Trigger the lazy loading by calling the import
  import('./Loop')
}

try{ LazyLoop.displayName ||= 'LazyLoop' } catch {}