import type {ImmersivePlugin, NavigationItem, PluginComponent} from '@github-ui/copilot-chat/plugin'
import {LazyLoop} from './components/LazyLoop'
import {
  CHAT_MODE_LOOPS,
  LOOP_REGEX,
  LOOP_SHARE_REGEX,
  LOOP_SHARE_ID_REGEX,
  LOOPS_PLUGIN_ID,
  LOOPS_PLUGIN_NAME,
  LOOPS_PATH,
  LOOPS_REGEX,
} from './utils/constants'
import loopBlocksExtension from './markdown-extensions/loop-blocks/LoopBlocksExtension'
import {LoopsService} from './service/loops-service'
import {ChatCompletionsClient} from './service/chat-completions-client'
import {GraphQLClient} from './service/graphql-client'
import {LoopsView} from './components/loops-view/LoopsView'
import type {CreateMessageStreamingParams} from '@github-ui/copilot-chat/utils/copilot-chat-service'
import {LoopsIcon} from '@github-ui/pacer/CustomIcon'
import {LoopsClient} from './service/loops-client'

export class LoopsPlugin implements ImmersivePlugin {
  id = LOOPS_PLUGIN_ID

  displayName = LOOPS_PLUGIN_NAME

  constructor(
    completionsApiUrl: string,
    graphqlApiUrl: string,
    clientUrl: string,
    ssoOrgIDs: string[],
    previewUrl: string,
    realIp?: string,
  ) {
    this.service = new LoopsService(
      new LoopsClient(clientUrl),
      new GraphQLClient(graphqlApiUrl, ssoOrgIDs),
      new ChatCompletionsClient(completionsApiUrl, ssoOrgIDs, realIp),
    )
    this.previewUrl = previewUrl
  }

  service: LoopsService

  previewUrl: string

  markdownExtensions = [loopBlocksExtension]

  skipSyncRouteToThread = true

  components: PluginComponent[] = [
    {
      id: 'loops-list',
      Component: LoopsView,
      routes: [LOOPS_REGEX],
    },
    {
      id: 'loop-detail',
      Component: LazyLoop,
      routes: [LOOP_REGEX, LOOP_SHARE_REGEX, LOOP_SHARE_ID_REGEX],
    },
  ]

  navigationItems: NavigationItem[] = [
    {
      id: LOOPS_PLUGIN_ID,
      displayName: 'Loops',
      href: LOOPS_PATH,
      icon: LoopsIcon,
    },
  ]

  async overrideCreateMessageOptions(options: CreateMessageStreamingParams): Promise<CreateMessageStreamingParams> {
    return {
      ...options,
      mode: CHAT_MODE_LOOPS,
    }
  }
}
