export interface TaskListItemProps {
  pullRequest: Pull
  state?: SessionState
  merged: boolean
  lastSessionStartDate?: string
  revisionCount: number
}

interface OpenTaskListProps extends TaskListProps {
  tasks: UITask[]
}

interface ClosedTaskListProps extends TaskListProps {
  tasks: HydratedTask[]
}

interface TaskListProps {
  isError: boolean
}

function OpenTaskList({tasks, isError}: OpenTaskListProps) {
  return (
    <ListBlock.List id="tasks-list" aria-labelledby="open-tab">
      {isError ? (
        <ListBlock.EmptyState>
          <AlertIcon size={24} />
          <p>Sorry, something went wrong</p>
        </ListBlock.EmptyState>
      ) : tasks.length === 0 ? (
        <ListBlock.EmptyState>
          <p>No open tasks yet. Start a new task to see it here.</p>
        </ListBlock.EmptyState>
      ) : (
        <>
          {tasks.map(task => {
            // Handle optimistic tasks (newly created tasks that haven't been confirmed by server yet)
            if (task.isOptimistic) {
              return (
                <OptimisticTaskListItem
                  key={task.clientGeneratedId}
                  title={`Creating: ${task.problemStatement ?? ''}`}
                  repositoryNwo={task.nwo ?? ''}
                />
              )
            }

            // Handle tasks with pull request data
            return (
              task.pull && (
                <TaskListItem
                  key={task.pull.id}
                  state={task.latest_session_state}
                  startedAt={task.latest_session_updated_at}
                  revisionCount={task.session_count - 1}
                  prState={task.pull.state}
                  prUrl={task.pull.url}
                  prTitle={task.pull.title}
                  prNwo={task.pull.repository_nwo}
                  prNumber={task.pull.number}
                  prInMergeQueue={task.pull.inMergeQueue ?? false}
                  prDiffStats={task.pull.diffstat}
                />
              )
            )
          })}
        </>
      )}
    </ListBlock.List>
  )
}

function ClosedTaskList({tasks, isError}: ClosedTaskListProps) {
  return (
    <ListBlock.List id="tasks-list" aria-labelledby="closed-tab">
      {isError ? (
        <ListBlock.EmptyState>
          <AlertIcon size={24} />
          <p>Sorry, something went wrong</p>
        </ListBlock.EmptyState>
      ) : tasks.length === 0 ? (
        <ListBlock.EmptyState>
          <p>No closed tasks yet.</p>
        </ListBlock.EmptyState>
      ) : (
        tasks.map(task => {
          return (
            <TaskListItem
              key={task.pull.id}
              state={task.latest_session_state}
              startedAt={task.latest_session_updated_at}
              revisionCount={task.session_count - 1}
              prState={task.pull.state}
              prUrl={task.pull.url}
              prTitle={task.pull.title}
              prNwo={task.pull.repository_nwo}
              prNumber={task.pull.number}
              prInMergeQueue={task.pull.inMergeQueue ?? false}
              prDiffStats={task.pull.diffstat}
            />
          )
        })
      )}
    </ListBlock.List>
  )
}

export function TaskList({
  tasks,
  isError,
  activeTab,
  setActiveTab,
}: {
  tasks: UITask[]
  isError: boolean
  activeTab: 'open' | 'closed'
  setActiveTab: (tab: 'open' | 'closed') => void
}) {
  const openTasks = tasks.filter(task => !task.pull || (task.pull.state !== 'merged' && task.pull.state !== 'closed'))
  const closedTasks = tasks.filter((task): task is HydratedTask =>
    Boolean(task.pull && (task.pull.state === 'merged' || task.pull.state === 'closed')),
  )

  return (
    <ListBlock>
      <ListBlock.Header>
        <div role="tablist" aria-label="Filter pull requests" className={styles.filterButtons}>
          <button
            onClick={() => setActiveTab('open')}
            role="tab"
            aria-selected={activeTab === 'open'}
            aria-controls="tasks-list"
            id="open-tab"
            className={styles.button}
          >
            Open <span className={styles.counter}>{openTasks.length}</span>
          </button>
          <button
            onClick={() => setActiveTab('closed')}
            role="tab"
            aria-selected={activeTab === 'closed'}
            aria-controls="tasks-list"
            id="closed-tab"
            className={styles.button}
          >
            Closed <span className={styles.counter}>{closedTasks.length}</span>
          </button>
        </div>
      </ListBlock.Header>
      {activeTab === 'open' ? (
        <OpenTaskList tasks={openTasks} isError={isError} />
      ) : (
        <ClosedTaskList tasks={closedTasks} isError={isError} />
      )}
    </ListBlock>
  )
}

export function AgentsViewWrapper() {
  return (
    <ConsecutiveCAPI401sProvider>
      <PacerLayout data-testid="agents-layout">
        <PacerLayout.Header>
          {/* An empty header that's needed for 1. cohesion with other views and 2. ensure that controls don't overlap with content
              on smaller viewports. This should stay until replaced with a general component. */}
          <div className={styles.header} />
        </PacerLayout.Header>

        <PacerLayout.Sidebar>
          <CopilotNavigationWithContext />
        </PacerLayout.Sidebar>

        <PacerLayout.ColumnLeft>
          <AgentsView />
        </PacerLayout.ColumnLeft>
      </PacerLayout>
    </ConsecutiveCAPI401sProvider>
  )
}

export function AgentsView() {
  const [activeTab, setActiveTab] = useState<'open' | 'closed'>('open')
  const {
    sessionsPollingInterval,
    showCopilotCodingAgentPremiumRequestsBanner,
    tasks: initialTasks,
    pullRequestsMap: initialPullRequestsMap,
  } = useAppPayload<MissionControlAppPayload>()

  const [failedTaskCreationAttempts, setFailedTaskCreationAttempts] = useState<
    Array<{nwo: string; problemStatement: string; error: Error; timestamp: string; baseRef?: string}>
  >([])

  // It's not necessary to get the `isLoading` state from useTasks since it only applies to the first fetch,
  // and we already have all the initial data we need from the app payload.
  const {tasks, isError} = useTasks({
    sessionsPollingInterval,
    initialTasks,
    initialPullRequestsMap,
  })

  const {createTask} = useCreateTask({
    onError: (error, variables) => {
      setFailedTaskCreationAttempts(prev => [
        ...prev,
        {
          ...variables,
          error,
          baseRef: variables.baseRef,
          timestamp: new Date().toISOString(),
        },
      ])
    },
  })

  const manager = useChatManager()

  useEffect(() => {
    // Set the title of the page
    setTitle('Agents · GitHub Copilot')
  }, [])

  useEffect(() => {
    // clear out the thread on mount
    manager.selectThread(null, {includeThreads: false, clearTopic: true})
  }, [manager])

  const handleUserSubmit = async (
    content: string,
    selectedRepo: DropdownRepository | null,
    selectedBranch: string,
    selectedSubAgent: string,
  ) => {
    const trimmedContent = content.trim()
    if (trimmedContent === '' || !selectedBranch || selectedBranch.trim() === '') return
    if (selectedRepo) {
      setActiveTab('open')

      // This mutation will automatically invalidate and refetch the tasks after completion
      createTask({
        nwo: selectedRepo.nameWithOwner,
        problemStatement: trimmedContent,
        baseRef: selectedBranch,
        eventType: 'agents_page',
        subagent: selectedSubAgent,
      })
    } else {
      manager.sendChatMessage({
        content: trimmedContent,
        thread: null,
        references: [],
      })
    }
  }

  // TODO: Now that we have uuids on the request, we might be able to use that to correlate requests and responses more easily.
  const handleRetry = (attemptIndex: number) => {
    const attempt = failedTaskCreationAttempts[attemptIndex]
    if (attempt) {
      // Remove this specific attempt from the list
      setFailedTaskCreationAttempts(prev => prev.filter((_, index) => index !== attemptIndex))
      createTask({
        nwo: attempt.nwo,
        problemStatement: attempt.problemStatement,
        baseRef: attempt.baseRef,
        eventType: 'agents_page',
      })
    }
  }

  const title = 'Agents'
  const description =
    "Delegate tasks to GitHub Copilot coding agent to work on in the background, and then monitor Copilot's progress."

  const {ssoOrganizations, currentReferences} = useChatState()
  const allProtectedOrgs = ssoOrganizations.map(org => org.login)
  const repoReference = currentReferences.find(ref => ref.type === 'repository')

  useEffect(() => {
    const cacheKey = 'PROTECTED_ORGS'
    const prevOrgs = sessionStorage.getItem(cacheKey)

    if (JSON.stringify(allProtectedOrgs) !== prevOrgs) {
      const tokenProvider = new AgentSessionsTokenProvider()
      tokenProvider.removeLocalStorageAuthToken()
      sessionStorage.setItem(cacheKey, JSON.stringify(allProtectedOrgs))
    }
  }, [allProtectedOrgs])
  const [bannerDismissed, setBannerDismissed] = useState(false)
  const initialRepo = repoReference ? {...repoReference, private: repoReference?.visibility === 'private'} : undefined
  return (
    <ContentView.Container width="small">
      {showCopilotCodingAgentPremiumRequestsBanner && !bannerDismissed && (
        <ContentView.Banner>
          <PremiumRequestsBanner onBannerDismiss={() => setBannerDismissed(true)} />
        </ContentView.Banner>
      )}
      <ContentView.Header>
        <ContentView.Title>{title}</ContentView.Title>
        <ContentView.Description>{description}</ContentView.Description>
      </ContentView.Header>
      {allProtectedOrgs.length > 0 && !isFeatureEnabled('global_sso_banner') && (
        <ContentView.Section>
          <SingleSignOnBanner protectedOrgs={allProtectedOrgs} redirectURI={() => location.href} />
        </ContentView.Section>
      )}
      <ContentView.Section>
        <NewTaskChatInput handleUserSubmit={handleUserSubmit} initialRepo={initialRepo as unknown as Repository} />
        {failedTaskCreationAttempts.length > 0 && (
          <Stack direction="vertical" className={styles.failedTaskCreationBanners}>
            {failedTaskCreationAttempts.map((attempt, index) => (
              <TaskCreationFailedBanner
                key={`${attempt?.nwo}-${attempt?.problemStatement}-${attempt?.timestamp}`}
                problemStatement={attempt?.problemStatement}
                handleRetry={() => handleRetry(index)}
                handleDismiss={() => {
                  setFailedTaskCreationAttempts(prev => prev.filter((_, i) => i !== index))
                }}
              />
            ))}
          </Stack>
        )}
      </ContentView.Section>

      <ContentView.Section>
        <TaskList tasks={tasks} isError={isError} activeTab={activeTab} setActiveTab={setActiveTab} />
      </ContentView.Section>
    </ContentView.Container>
  )
}

try{ OpenTaskList.displayName ||= 'OpenTaskList' } catch {}
try{ ClosedTaskList.displayName ||= 'ClosedTaskList' } catch {}
try{ TaskList.displayName ||= 'TaskList' } catch {}
