import {ActionMenu, IconButton, type IconButtonProps} from '@primer/react'
import {useRef} from 'react' // Removed useCallback import
import {KebabHorizontalIcon} from '@primer/octicons-react'
import {LoopsActionMenuOverlay} from './LoopsActionMenuOverlay'

interface LoopsContextMenuProps {
  onDelete?: () => void
  onCopyLoop?: () => void
  onDuplicate?: (loopId: string) => void
  onShare?: () => void
  onEdit?: () => void
  onCopyOutput?: () => void
  loopId?: string
  variant?: IconButtonProps['variant']
  hasOutput?: boolean
}

export function LoopsContextMenu({
  onDelete,
  onCopyLoop,
  onDuplicate,
  onShare,
  onEdit,
  onCopyOutput,
  loopId,
  variant = 'invisible',
  hasOutput,
}: LoopsContextMenuProps) {
  const anchorRef = useRef<HTMLButtonElement>(null)

  if (!loopId) return null

  return (
    <ActionMenu anchorRef={anchorRef}>
      <ActionMenu.Anchor>
        <IconButton icon={KebabHorizontalIcon} aria-label="Manage loop" variant={variant} />
      </ActionMenu.Anchor>
      <LoopsActionMenuOverlay
        onDelete={onDelete}
        onCopyLoop={onCopyLoop}
        onDuplicate={onDuplicate}
        onShare={onShare}
        onEdit={onEdit}
        onCopyOutput={onCopyOutput}
        hasOutput={hasOutput}
        loopId={loopId}
        returnFocusRef={anchorRef}
      />
    </ActionMenu>
  )
}

try{ LoopsContextMenu.displayName ||= 'LoopsContextMenu' } catch {}