import {ContentView} from '@github-ui/pacer/ContentView'
import {ListBlock} from '@github-ui/pacer/ListBlock'
import styles from './LoopsView.module.css'
import type {ImmersivePlugin} from '@github-ui/copilot-chat/plugin'
import {ChatInput} from '@github-ui/copilot-chat/components/ChatInput'
import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
import {useAllLoops} from '../../hooks/queries/use-all-loops'
import {useEffect, useState, useMemo} from 'react'
import {COPILOT_PATH} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import {SearchInput} from '@github-ui/pacer/SearchInput'
import {useLocalStorage} from '@github-ui/use-safe-storage/local-storage'
import {isLoopsPlugin} from '../../utils/plugin'
import {LoopsViewHeader} from './LoopsViewHeader'
import {staffExamples} from '../../example-loops/staff-examples'
import type {Loop} from '../../types/app'
import {setTitle} from '@github-ui/document-metadata'
import {useNavigate} from '@github-ui/react-router'
import {LoopsServiceProvider, useLoopsService} from '../../contexts/LoopsServiceProvider'
import {LoopIcon} from '@primer/octicons-react'
import {sendEvent} from '@github-ui/hydro-analytics'
import {setLoopThreadId} from '../../utils/loop-thread-storage'
import {useDefaultModel} from '@github-ui/copilot-chat/utils/models'
import type {CopilotChatState} from '@github-ui/copilot-chat/utils/copilot-chat-reducer'
import {preloadLoopComponent} from '../LazyLoop'
import {CHAT_MODE_LOOPS, LOOPS_PLUGIN_ID} from '../../utils/constants'
import {ListModeToggle} from './ListModeToggle'
import {LoopOutput} from './LoopOutput'
import outputListStyles from './LoopsOutputList.module.css'
import {AppContextProvider} from '../../contexts/AppContextProvider'
import {LoopsContextMenu} from '../controls/LoopsContextMenu'
import {Layout as PacerLayout} from '@github-ui/pacer/Layout'
import {CopilotNavigationWithContext} from '@github-ui/copilot-chat/components/navigation/CopilotNavigation'

export interface LoopsViewProps {
  chatState: CopilotChatState
  plugin?: ImmersivePlugin
}

export function LoopsView({chatState, plugin}: LoopsViewProps) {
  if (!plugin || !isLoopsPlugin(plugin)) throw new Error('LoopsView can only be used with a LoopsPlugin')
  return (
    <PacerLayout data-testid="loops-layout">
      <PacerLayout.Header>
        <LoopsViewHeader />
      </PacerLayout.Header>

      <PacerLayout.Sidebar>
        <CopilotNavigationWithContext />
      </PacerLayout.Sidebar>

      <PacerLayout.ColumnLeft>
        <AppContextProvider previewUrl={plugin.previewUrl} availableModels={[]} sendChatMessage={() => {}}>
          <LoopsServiceProvider value={plugin.service}>
            <LoopsViewInner chatState={chatState} />
          </LoopsServiceProvider>
        </AppContextProvider>
      </PacerLayout.ColumnLeft>
    </PacerLayout>
  )
}

function LoopsViewInner({chatState}: {chatState: CopilotChatState}) {
  const {data: loops, isLoading} = useAllLoops()
  const manager = useChatManager()
  const navigate = useNavigate()
  const loopsService = useLoopsService()
  const defaultModel = useDefaultModel(chatState.availableModels)
  const [viewMode, setViewMode] = useLocalStorage('loopsOverviewViewMode', 'output' as 'list' | 'output')
  const [searchQuery, setSearchQuery] = useState('')

  // Filter loops based on search query
  const filteredLoops = useMemo(() => {
    if (!loops || !searchQuery.trim()) {
      return loops
    }
    const query = searchQuery.toLowerCase().trim()
    return loops.filter(
      loop =>
        loop.title.toLowerCase().includes(query) ||
        (loop.description && loop.description.toLowerCase().includes(query)),
    )
  }, [loops, searchQuery])

  useEffect(() => {
    // Set the page title when component mounts
    setTitle('Loops · GitHub Copilot')

    // Preload Loop to warm the component for when users navigate to loops
    preloadLoopComponent()
  }, [])

  useEffect(() => {
    // clear out the thread on mount
    manager.selectThread(null, {includeThreads: false, clearTopic: true})
  }, [manager])

  const handleUserSubmit = async (content: string) => {
    const trimmedContent = content.trim()
    if (trimmedContent === '') return

    sendEvent('dotcom_chat.activate', {target: 'OVERVIEW_INITIAL_CREATE', mode: 'loops'})

    const newLoopId = crypto.randomUUID()

    const opts = {scopeId: LOOPS_PLUGIN_ID}
    const thread = await manager.createThread(opts)
    await loopsService.createLoop(newLoopId)
    setLoopThreadId(newLoopId, thread.id)

    const chatMessageParams = {
      content: trimmedContent,
      model: defaultModel,
      references: [],
      thread,
      mode: CHAT_MODE_LOOPS,
    }

    manager.sendChatMessage(chatMessageParams)
    navigate(`${COPILOT_PATH}/l/${newLoopId}`)
  }

  const createThreadWithLoop = async (loop: Loop) => {
    await loopsService.createLoop(loop)
    navigate(`${COPILOT_PATH}/l/${loop.id}`)
  }

  const handleViewModeChange = (mode: 'list' | 'output') => {
    setViewMode(mode)
  }

  const handleSearch = (query: string) => {
    setSearchQuery(query)
    sendEvent('dotcom_chat.activate', {target: 'LOOPS_SEARCH', mode: 'loops'})
  }

  return (
    <ContentView.Container width="small">
      <div className={styles.header}>
        <ContentView.Header>
          <ContentView.Title>Loops</ContentView.Title>
          <ContentView.Description>
            Automate repetitive tasks by simply describing them using natural language. Automate once. Loop forever.
          </ContentView.Description>
        </ContentView.Header>
        <div className={styles.input}>
          <ChatInput
            modes={[
              {
                name: 'Loop',
                icon: <LoopIcon />,
                submitLabel: 'Automate',
                placeholder: 'What would you like to automate?',
              },
            ]}
            size="large"
            onSubmit={handleUserSubmit}
          />
        </div>
      </div>
      {isLoading || (loops && loops.length > 0) ? (
        <ContentView.Section>
          <div className={styles.searchContainer}>
            <SearchInput
              onSearch={handleSearch}
              placeholder="Search loops..."
              aria-label="Search loops"
              debounceDelay={300}
            />
            <ListModeToggle value={viewMode} onChange={handleViewModeChange} />
          </div>
          {searchQuery && filteredLoops && filteredLoops.length === 0 ? (
            <div className={styles.noResultsMessage}>No loops found matching &ldquo;{searchQuery}&rdquo;</div>
          ) : viewMode === 'list' ? (
            <ListBlock>
              <ListBlock.List loading={isLoading}>
                {filteredLoops?.map(item => (
                  <ListBlock.Item
                    key={item.id}
                    href={`${COPILOT_PATH}/l/${item.id}`}
                    onClick={() =>
                      sendEvent('dotcom_chat.activate', {target: 'OVERVIEW_USER_LOOP_SELECT', mode: 'loops'})
                    }
                  >
                    <ListBlock.Item.Title>{item.title}</ListBlock.Item.Title>
                    <ListBlock.Item.Description>{item.description}</ListBlock.Item.Description>
                    <ListBlock.Item.Actions>
                      <LoopsContextMenu loopId={item.id} />
                    </ListBlock.Item.Actions>
                  </ListBlock.Item>
                ))}
              </ListBlock.List>
            </ListBlock>
          ) : (
            <div className={outputListStyles.list}>
              {(filteredLoops || []).map(loop => (
                <LoopOutput key={loop.id} loop={loop} />
              ))}
            </div>
          )}
        </ContentView.Section>
      ) : null}
      {!isLoading && (!loops || loops.length === 0) && (
        <ContentView.Section>
          <ContentView.Section.Title>Examples</ContentView.Section.Title>
          <ListBlock>
            <ListBlock.List loading={isLoading}>
              {staffExamples.map(({altText: _altText, assetPath: _assetPath, loop: exampleLoop}) => (
                <ListBlock.Item
                  key={exampleLoop.title}
                  onClick={() => {
                    sendEvent('dotcom_chat.activate', {target: 'OVERVIEW_EXAMPLE_LOOP_SELECT', mode: 'loops'})
                    const newLoop: Loop = {
                      ...exampleLoop,
                      id: crypto.randomUUID(),
                      updatedAt: Date.now(),
                      owned: true,
                      visibility: 'private',
                    }
                    createThreadWithLoop(newLoop)
                  }}
                >
                  <ListBlock.Item.Title>{exampleLoop.title}</ListBlock.Item.Title>
                  <ListBlock.Item.Description>{exampleLoop.description}</ListBlock.Item.Description>
                </ListBlock.Item>
              ))}
            </ListBlock.List>
          </ListBlock>
        </ContentView.Section>
      )}
    </ContentView.Container>
  )
}

try{ LoopsView.displayName ||= 'LoopsView' } catch {}
try{ LoopsViewInner.displayName ||= 'LoopsViewInner' } catch {}