import {SquareFillIcon, SyncIcon, TriangleDownIcon} from '@primer/octicons-react'
import {IconButton, Button, ActionList, ActionMenu, ButtonGroup} from '@primer/react'
import type {IconButtonProps, ButtonProps} from '@primer/react'
import type {NodeValue} from '../../types/app'
import type React from 'react'

interface ExecuteButtonProps {
  value?: NodeValue
  className?: string
  size?: 'small' | 'medium' | 'large'
  isLoading: boolean
  onClick: (e: React.MouseEvent<HTMLButtonElement>) => void
  onStop?: (e: React.MouseEvent<HTMLButtonElement>) => void
  variant?: IconButtonProps['variant'] | ButtonProps['variant']
  disabled?: boolean
  iconOnly?: boolean
  showPickInputsOption?: boolean
  onRunWithInputs?: () => void
  leadingVisual?: ButtonProps['leadingVisual']
}

export function ExecuteButton({
  value,
  isLoading,
  onClick,
  onStop,
  variant = 'invisible',
  disabled,
  iconOnly,
  showPickInputsOption = false,
  onRunWithInputs,
  leadingVisual,
}: ExecuteButtonProps) {
  const getAriaLabel = () => {
    if (isLoading) return 'Loading...'
    return value ? 'Run node' : 'Run loop'
  }

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (isLoading) {
      onStop?.(e)
    } else {
      onClick(e)
    }
  }

  const handleRunWithInputs = () => {
    onRunWithInputs?.()
  }

  // Show split button when showPickInputsOption is true and not loading
  if (showPickInputsOption && !isLoading && !iconOnly) {
    return (
      <ButtonGroup>
        <Button disabled={disabled} variant={variant} onClick={handleClick} leadingVisual={leadingVisual}>
          Run
        </Button>
        <ActionMenu>
          <ActionMenu.Button
            disabled={disabled}
            variant={variant}
            icon={TriangleDownIcon}
            aria-label="More run options"
          />
          <ActionMenu.Overlay>
            <ActionList>
              <ActionList.Item onSelect={handleRunWithInputs}>Run with custom inputs</ActionList.Item>
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </ButtonGroup>
    )
  }

  if (!iconOnly) {
    return (
      <Button
        disabled={disabled}
        variant={isLoading ? 'danger' : variant}
        onClick={handleClick}
        leadingVisual={leadingVisual}
      >
        {isLoading ? 'Stop' : 'Run'}
      </Button>
    )
  }

  return (
    <IconButton
      disabled={disabled}
      aria-label={getAriaLabel()}
      icon={isLoading ? SquareFillIcon : SyncIcon}
      onClick={handleClick}
      variant={isLoading ? 'danger' : variant}
    />
  )
}

try{ ExecuteButton.displayName ||= 'ExecuteButton' } catch {}