import {useMutation, useQueryClient, type UseMutationOptions} from '@github-ui/react-query'
import {useDebounce} from '@github-ui/use-debounce'
import {useLoopsService} from '../../contexts/LoopsServiceProvider'
import {getLoopQueryKey} from '../queries/use-loop'
import type {Loop} from '../../types/app'
import type {Result} from '../../service/result'
import {draftVersion} from '../../utils/versions'

function useUpdateLoopInternal(
  args?: UseMutationOptions<
    Result<Loop>,
    Error,
    {loopID: string; updateFn: (loop: Loop | null) => Loop},
    {previousDraftLoop?: Loop; previousVersionedLoop?: Loop | null; loopID: string}
  >,
) {
  const loopsService = useLoopsService()

  return useMutation({
    mutationFn: async ({loopID, updateFn}) => {
      return await loopsService.updateLoop(loopID, updateFn)
    },
    ...args,
  })
}

export function useUpdateLoop() {
  const queryClient = useQueryClient()

  return useUpdateLoopInternal({
    onMutate: async ({loopID, updateFn}) => {
      // Cancel any outgoing refetches so they don't overwrite our optimistic update
      await queryClient.cancelQueries({queryKey: getLoopQueryKey(loopID, draftVersion)})

      // Snapshot the previous value
      const previousDraftLoop = queryClient.getQueryData<Loop>(getLoopQueryKey(loopID, draftVersion))
      const previousVersionedLoop = previousDraftLoop?.version
        ? queryClient.getQueryData<Loop>(getLoopQueryKey(loopID, previousDraftLoop.version))
        : null

      // Optimistically update to the new value
      if (previousDraftLoop) {
        const optimisticLoop = updateFn(previousDraftLoop)
        queryClient.setQueryData(getLoopQueryKey(loopID, draftVersion), optimisticLoop)
        if (optimisticLoop.version) {
          queryClient.setQueryData(getLoopQueryKey(loopID, optimisticLoop.version), optimisticLoop)
        }
      }

      // Return a context object with the snapshotted value
      return {previousDraftLoop, previousVersionedLoop, loopID}
    },
    onError: (_err, _variables, context) => {
      if (!context?.previousDraftLoop) return

      queryClient.setQueryData(getLoopQueryKey(context.loopID, draftVersion), context.previousDraftLoop)
      if (context.previousVersionedLoop && context.previousDraftLoop.version) {
        queryClient.setQueryData(
          getLoopQueryKey(context.loopID, context.previousDraftLoop.version),
          context.previousVersionedLoop,
        )
      }
    },
  })
}

/**
 * This hook implements a two-phase approach:
 * 1. Immediate cache updates for UX
 * 2. Debounced storage calls to avoid hitting storage on every keystroke
 *
 * Note: we only write granular updates to the `draft` version of the loop. Eventually, this will become a new version
 * of the loop when saved. This allows us to keep the latest version intact while users are editing.
 */
export function useUpdateLoopDebounced() {
  const queryClient = useQueryClient()
  const storageMutation = useUpdateLoopInternal()

  const debouncedStorageUpdate = useDebounce(storageMutation.mutate, 500)

  // Main mutation function that handles immediate cache updates + debounced write
  const mutate = async (
    {loopID, updateFn}: {loopID: string; updateFn: (loop: Loop | null) => Loop},
    options?: {onSuccess?: () => void},
  ) => {
    await queryClient.cancelQueries({queryKey: getLoopQueryKey(loopID, draftVersion)})
    const previousLoop = queryClient.getQueryData<Loop | null>(getLoopQueryKey(loopID, draftVersion))

    // Optimistically update the cache
    const updatedLoop = updateFn(previousLoop ?? null)
    queryClient.setQueryData(getLoopQueryKey(loopID, draftVersion), updatedLoop)

    debouncedStorageUpdate({loopID, updateFn})

    options?.onSuccess?.()

    return updatedLoop
  }

  return {
    ...storageMutation,
    mutate,
  }
}
