import {ObservableValue} from '@github-ui/observable'
import {createContext, type Dispatch, useContext, type PropsWithChildren, useCallback} from 'react'
import {useDerivedObservable, useObservableValue, useObservedState} from '@github-ui/react-observable'
import {useLayoutEffect} from '@github-ui/use-layout-effect'
import type {LoopsAction} from '../state/loops-action'
import {defaultLoopsState, type LoopsState} from '../state/loops-state'
import {useLoopsReducer} from '../hooks/use-loops-reducer'

const LoopsStateContext = createContext(new ObservableValue(defaultLoopsState))
const LoopsDispatchContext = createContext<Dispatch<LoopsAction>>(() => {})

export function LoopsStateProvider({children}: PropsWithChildren) {
  const [state, _dispatch] = useLoopsReducer()

  const stateObservable = useObservableValue(state)
  useLayoutEffect(() => {
    // eslint-disable-next-line react-hooks/react-compiler
    stateObservable.value = state
  }, [state, stateObservable])

  // This might look stupid, but putting a breakpoint in here makes
  // it a lot easier to debug where actions are getting dispatched from
  const dispatch: Dispatch<LoopsAction> = useCallback(
    (action: LoopsAction) => {
      _dispatch(action)
    },
    [_dispatch],
  )

  return (
    <LoopsStateContext.Provider value={stateObservable}>
      <LoopsDispatchContext.Provider value={dispatch}>{children}</LoopsDispatchContext.Provider>
    </LoopsStateContext.Provider>
  )
}

export function useLoopsStateLens<T>(lens: (state: LoopsState) => T): T {
  const o = useContext(LoopsStateContext)
  if (!o) throw new Error('useLoopsStateLens can only be used inside a PipesProvider')
  const valueObservable = useDerivedObservable(o, lens)
  return useObservedState(valueObservable)
}

export function useLoopsDispatch() {
  return useContext(LoopsDispatchContext)
}

try{ LoopsStateContext.displayName ||= 'LoopsStateContext' } catch {}
try{ LoopsDispatchContext.displayName ||= 'LoopsDispatchContext' } catch {}
try{ LoopsStateProvider.displayName ||= 'LoopsStateProvider' } catch {}