import {ExecuteButton} from '../controls/ExecuteButton'
import {LoopsContextMenu} from '../controls/LoopsContextMenu'
import {useLoopExecution} from '../../hooks/queries/use-loop-execution'
import {useRunLoopStandalone} from '../../hooks/use-run-loop-standalone'
import {getOutputNodes} from '../../utils/loops'
import {stringifyNodeValue} from '../../utils/utils'
import {isExecutionRunning} from '../../utils/execution-helpers'
import type {Loop} from '../../types/app'
import styles from './LoopOutput.module.css'
import {COPILOT_PATH} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import {sendEvent} from '@github-ui/hydro-analytics'
import {ExecutionView} from '../shared/ExecutionView'
import {Button} from '@github-ui/pacer/Button'

export function LoopOutput({loop}: {loop: Loop}) {
  const {runLoop, stopLoop, isPreparing} = useRunLoopStandalone()
  const firstOutputNode = getOutputNodes(loop)[0]
  const {data: execution} = useLoopExecution(loop)
  const nodeState = firstOutputNode ? execution?.nodes[firstOutputNode.id] : undefined
  const nodeValue = nodeState?.value ?? null
  const nodeError = nodeState?.error || null
  const isRunning = isExecutionRunning(execution)
  const isLoading = isPreparing || isRunning
  const valueString = stringifyNodeValue(nodeValue)

  const handleRun = async () => {
    await runLoop(loop)
    sendEvent('dotcom_chat.activate', {target: 'OUTPUTS_VIEW_LOOP_RUN', mode: 'loops'})
  }

  const handleStop = () => {
    stopLoop(loop)
    sendEvent('dotcom_chat.activate', {target: 'OUTPUTS_VIEW_LOOP_STOP', mode: 'loops'})
  }

  const handleEdit = () => {
    sendEvent('dotcom_chat.activate', {target: 'OUTPUTS_VIEW_EDIT_LOOP', mode: 'loops'})
  }

  const handleCopyOutput = async () => {
    if (!nodeValue) return
    try {
      await navigator.clipboard.writeText(valueString)
      sendEvent('dotcom_chat.activate', {target: 'OUTPUTS_VIEW_COPY_OUTPUT', mode: 'loops'})
    } catch {
      // Silently fail if clipboard access is not available
    }
  }

  return (
    <div className={styles.panel}>
      <div className={styles.header}>
        <h3 className={styles.title}>
          <Button variant="invisible" condensed to={`${COPILOT_PATH}/l/${loop.id}`} onClick={handleEdit}>
            {loop.title}
          </Button>
        </h3>
        <div className={styles.actions}>
          <ExecuteButton
            isLoading={isLoading}
            onClick={handleRun}
            onStop={handleStop}
            value={nodeValue}
            variant="invisible"
            iconOnly
          />
          <LoopsContextMenu
            loopId={loop.id}
            onEdit={handleEdit}
            onCopyOutput={handleCopyOutput}
            hasOutput={!!nodeValue}
          />
        </div>
      </div>
      <div className={styles.body}>
        <ExecutionView
          outputNodeExists={!!firstOutputNode}
          isRunning={isLoading}
          nodeValue={nodeValue}
          nodeError={nodeError}
          onRun={handleRun}
          onStop={handleStop}
        />
      </div>
    </div>
  )
}

try{ LoopOutput.displayName ||= 'LoopOutput' } catch {}