import {MarkGithubIcon, ThreeBarsIcon, XIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import {type ReactNode, type RefObject, useId} from 'react'
import {Button} from '../Button'

import styles from './Sidebar.module.css'
import {useProvidedRefOrCreate} from '@primer/react'
import {Tooltip} from '../Tooltip'

interface SidebarProps {
  children: ReactNode
  className?: string
  isFloating: boolean
  isVisible: boolean
  isExpanded: boolean
  sidebarRef?: RefObject<HTMLDivElement>
  onToggle: () => void
  'data-testid'?: string
}

/**
 * Generic sidebar component that can be used in various layouts.
 */
export function Sidebar({
  children,
  className,
  isVisible,
  isExpanded,
  sidebarRef,
  onToggle,
  'data-testid': dataTestId,
}: SidebarProps) {
  const isCondensed = !isExpanded

  const ref = useProvidedRefOrCreate(sidebarRef)

  const id = useId()

  const renderSidebarIcon = () => {
    return isVisible ? <XIcon /> : <ThreeBarsIcon />
  }

  return (
    <aside
      aria-labelledby={`${id}-copilot-navigation`}
      ref={ref}
      className={clsx(styles.container, className, {
        [styles.visible]: isVisible,
        [styles.condensed]: isCondensed,
      })}
      data-testid={dataTestId}
    >
      <div className={styles.sidebar}>
        <div className={styles.header}>
          <h2 id={`${id}-copilot-navigation`} className="sr-only">
            Copilot navigation
          </h2>
          <a href="/" target="_self" className={styles.githubLogo} aria-label="GitHub homepage">
            <MarkGithubIcon size={32} />
          </a>
          <Button
            className={styles.toggleSidebarFloating}
            aria-label={isVisible ? 'Close sidebar' : 'Open sidebar'}
            onClick={onToggle}
            iconOnly
            variant={isVisible ? 'invisible' : 'default'}
            icon={renderSidebarIcon()}
          />
        </div>
        {children}
      </div>
      <div className={styles.toggleSidebarContainer}>
        <Tooltip text={isVisible || isExpanded ? 'Condense' : 'Expand'} offset={isExpanded ? -8 : 0}>
          <button
            className={styles.toggleSidebarVertical}
            aria-label={isVisible || isExpanded ? 'Condense sidebar' : 'Expand sidebar'}
            onClick={onToggle}
          >
            {/* eslint-disable-next-line github/a11y-svg-has-accessible-name */}
            <svg
              width="16"
              height="16"
              viewBox="0 0 16 16"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
              strokeLinejoin="round"
              className={styles.toggleIcon}
            >
              <path
                d="M8 2.75 L8 8"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                className={styles.iconLineTop}
              />
              <path
                d="M8 13.25 L8 8"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                className={styles.iconLineBottom}
              />
            </svg>
          </button>
        </Tooltip>
      </div>
    </aside>
  )
}

try{ Sidebar.displayName ||= 'Sidebar' } catch {}