import {ActionList, ActionMenu, ConfirmationDialog} from '@primer/react'
import {useState, type RefObject} from 'react'
import {TrashIcon, CopyIcon, DuplicateIcon, LinkIcon, PencilIcon} from '@primer/octicons-react'
import {useDeleteLoop} from '../../hooks/mutations/use-delete-loop'
import {sendEvent} from '@github-ui/hydro-analytics'
import {COPILOT_PATH} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import {Link} from '@github-ui/react-router'

interface LoopsActionMenuOverlayProps {
  onDelete?: () => void
  onCopyLoop?: () => void
  onDuplicate?: (loopId: string) => void
  onShare?: () => void
  onEdit?: () => void
  onCopyOutput?: () => void
  hasOutput?: boolean
  onRename?: () => void
  loopId?: string
  returnFocusRef?: RefObject<HTMLElement>
}

export function LoopsActionMenuOverlay({
  onDelete,
  onCopyLoop,
  onDuplicate,
  onShare,
  onEdit,
  onCopyOutput,
  onRename,
  loopId,
  hasOutput = false,
  returnFocusRef,
}: LoopsActionMenuOverlayProps) {
  const [visibleDialog, setVisibleDialog] = useState<'delete' | null>(null)
  const {mutate: deleteLoop} = useDeleteLoop()

  const handleOpenDeleteDialog = () => {
    setVisibleDialog('delete')
  }

  const handleCloseDialog = () => {
    setVisibleDialog(null)
    setTimeout(() => returnFocusRef?.current?.focus())
  }

  const handleDeleteConfirm = async () => {
    if (!loopId) return

    setVisibleDialog(null)
    deleteLoop(loopId, {onSuccess: onDelete})
  }

  const handleDuplicateLoop = () => {
    if (!loopId || !onDuplicate) return

    sendEvent('dotcom_chat.activate', {target: 'LOOP_DUPLICATE', mode: 'loops'})
    onDuplicate(loopId)
  }

  const handleShareLoop = () => {
    onShare?.()
  }

  const handleEdit = () => {
    sendEvent('dotcom_chat.activate', {target: 'OUTPUTS_VIEW_EDIT_LOOP', mode: 'loops'})
    onEdit?.()
  }

  const handleCopyOutput = () => {
    if (!onCopyOutput) return
    onCopyOutput()
  }

  if (!loopId) return null

  return (
    <>
      <ActionMenu.Overlay align="end">
        <ActionList>
          {onCopyOutput && (
            <ActionList.Item onSelect={handleCopyOutput} disabled={!hasOutput}>
              <ActionList.LeadingVisual>
                <CopyIcon />
              </ActionList.LeadingVisual>
              Copy output
            </ActionList.Item>
          )}
          {onEdit && (
            <ActionList.LinkItem as={Link} to={`${COPILOT_PATH}/l/${loopId}`} onSelect={handleEdit}>
              <ActionList.LeadingVisual>
                <PencilIcon />
              </ActionList.LeadingVisual>
              Edit loop
            </ActionList.LinkItem>
          )}
          {(onCopyOutput || onEdit) && (onDuplicate || onShare || onCopyLoop) && <ActionList.Divider />}
          {onDuplicate && (
            <ActionList.Item onSelect={handleDuplicateLoop}>
              <ActionList.LeadingVisual>
                <DuplicateIcon />
              </ActionList.LeadingVisual>
              Duplicate
            </ActionList.Item>
          )}
          {onRename && (
            <ActionList.Item onSelect={onRename}>
              <ActionList.LeadingVisual>
                <PencilIcon />
              </ActionList.LeadingVisual>
              Rename
            </ActionList.Item>
          )}
          {onShare && (
            <ActionList.Item onSelect={handleShareLoop}>
              <ActionList.LeadingVisual>
                <LinkIcon />
              </ActionList.LeadingVisual>
              Copy link
            </ActionList.Item>
          )}
          {onCopyLoop && (
            <ActionList.Item onSelect={onCopyLoop}>
              <ActionList.LeadingVisual>
                <CopyIcon />
              </ActionList.LeadingVisual>
              Copy JSON
            </ActionList.Item>
          )}
          {(onDuplicate || onShare || onCopyLoop) && <ActionList.Divider />}
          <ActionList.Item variant="danger" onSelect={handleOpenDeleteDialog}>
            <ActionList.LeadingVisual>
              <TrashIcon />
            </ActionList.LeadingVisual>
            Delete
          </ActionList.Item>
        </ActionList>
      </ActionMenu.Overlay>

      {visibleDialog === 'delete' && (
        <ConfirmationDialog
          title="Delete loop"
          onClose={gesture => {
            if (gesture === 'confirm') {
              handleDeleteConfirm()
            } else {
              handleCloseDialog()
            }
          }}
          confirmButtonContent="Delete"
          confirmButtonType="danger"
        >
          Are you sure you want to delete this loop? This action cannot be undone.
        </ConfirmationDialog>
      )}
    </>
  )
}

try{ LoopsActionMenuOverlay.displayName ||= 'LoopsActionMenuOverlay' } catch {}