import {useState, useCallback} from 'react'
import {useLoopsService} from '../contexts/LoopsServiceProvider'
import {logError} from '../utils/console'
import type {Loop} from '../types/app'
import {useQueryClient} from '@github-ui/react-query'
import {loopExecutionQueryKey} from './queries/use-loop-execution'
import type {Execution} from '../types/execution'
import {ErrorResult, SuccessResult} from '../service/result'
import {executionQueryKey} from './queries/use-execution'
import type {LoopRunnerAction} from '../service/loop-runner'
import {draftVersion} from '../utils/versions'

/**
 * Standalone hook for running loops from the overview without requiring loop context.
 * Unlike useRunLoop, this doesn't depend on URL params or current loop state.
 *
 * NOTE: This hook intentionally duplicates logic from useRunPipeline as a temporary solution.
 * When versioning system changes are implemented, we'll reconcile these hooks with proper
 * abstraction to handle the different execution contexts.
 */
export function useRunLoopStandalone() {
  const service = useLoopsService()
  const queryClient = useQueryClient()
  const [isPreparing, setIsPreparing] = useState(false)

  const runLoop = useCallback(
    async (loop: Loop) => {
      setIsPreparing(true)

      try {
        // Create a fresh execution for this loop
        const createExecutionResult = await service.createExecution(loop.id, loop.version || draftVersion)
        if (!createExecutionResult.success) {
          throw new Error(`Failed to create execution: ${createExecutionResult.error}`)
        }
        const execution = createExecutionResult.data

        // Create a progress handler that updates the query cache
        const progressHandler = (action: LoopRunnerAction) => {
          const executionQueryKeys = executionQueryKey(loop.id, loop.version || draftVersion)
          const loopExecutionQueryKeys = loopExecutionQueryKey(loop.id, loop.version || draftVersion)

          switch (action.type) {
            case 'UPDATE_NODE_VALUE':
            case 'UPDATE_NODE_VALUE_PARTIAL':
              {
                const updateFn = (currentExecution: Execution | null | undefined) => {
                  if (!currentExecution) return null
                  return {
                    ...currentExecution,
                    nodes: {
                      ...currentExecution.nodes,
                      [action.nodeID]: {
                        ...currentExecution.nodes[action.nodeID],
                        value: action.value,
                        completedAt: action.type === 'UPDATE_NODE_VALUE' ? Date.now() : undefined,
                      },
                    },
                  }
                }
                queryClient.setQueryData<Execution | null>(executionQueryKeys, updateFn)
                queryClient.setQueryData<Execution | null>(loopExecutionQueryKeys, updateFn)
              }
              break
            case 'UPDATE_NODE_ERROR':
              {
                const updateFn = (currentExecution: Execution | null | undefined) => {
                  if (!currentExecution) return null
                  return {
                    ...currentExecution,
                    nodes: {
                      ...currentExecution.nodes,
                      [action.nodeID]: {
                        ...currentExecution.nodes[action.nodeID],
                        error: action.error,
                        completedAt: Date.now(),
                      },
                    },
                  }
                }
                queryClient.setQueryData<Execution | null>(executionQueryKeys, updateFn)
                queryClient.setQueryData<Execution | null>(loopExecutionQueryKeys, updateFn)
              }
              break
            case 'SET_RUNNING':
              {
                const updateFn = (currentExecution: Execution | null | undefined) => {
                  if (!currentExecution) return null
                  return {
                    ...currentExecution,
                    nodes: {
                      ...currentExecution.nodes,
                      [action.nodeID]: {
                        ...currentExecution.nodes[action.nodeID],
                        completedAt: undefined,
                        startedAt: Date.now(),
                      },
                    },
                  }
                }
                queryClient.setQueryData<Execution | null>(executionQueryKeys, updateFn)
                queryClient.setQueryData<Execution | null>(loopExecutionQueryKeys, updateFn)
              }
              break
          }
        }

        // Create a getExecution function that works with this specific loop
        const getExecution = (loopID: string, version: string, _executionID: string) => {
          const currentExecutionQueryKeys = executionQueryKey(loopID, version)
          const currentExecution = queryClient.getQueryData<Execution | null>(currentExecutionQueryKeys)
          return Promise.resolve(
            currentExecution ? SuccessResult(currentExecution) : ErrorResult('execution not found'),
          )
        }

        // Set the initial execution in the cache
        const executionQueryKeys = executionQueryKey(loop.id, loop.version || draftVersion)
        const loopExecutionQueryKeys = loopExecutionQueryKey(loop.id, loop.version || draftVersion)
        queryClient.setQueryData(executionQueryKeys, execution)
        queryClient.setQueryData(loopExecutionQueryKeys, execution)

        setIsPreparing(false)

        // Run the pipeline
        await service.runPipeline(loop, execution.id, progressHandler, getExecution)
      } catch (error) {
        setIsPreparing(false)
        logError('Error running loop:', error)
        throw error
      }
    },
    [service, queryClient],
  )

  const stopLoop = useCallback(
    (loop: Loop) => {
      // Find the current execution for this loop
      const executionQueryKeys = executionQueryKey(loop.id, loop.version || draftVersion)
      const execution = queryClient.getQueryData<Execution | null>(executionQueryKeys)
      if (!execution) return

      service.stopPipeline(execution.id, () => {
        // Invalidate the execution queries
        queryClient.invalidateQueries({queryKey: executionQueryKeys})
        queryClient.invalidateQueries({
          queryKey: loopExecutionQueryKey(loop.id, loop.version || draftVersion),
        })
      })
    },
    [service, queryClient],
  )

  return {runLoop, stopLoop, isPreparing}
}
